    const at = Date.now(), helperId = randomUUID(), outgoingId = randomUUID();
    const rows = [
      { id: helperId, sessionId: null, text: 'Original retained planner.', mode: 'auto', dueAt: 0,
        model: null, reasoningEffort: null, purpose: 'decision', lifetime: 'temporary-planner',
        decisionSourceSessionId: f.sessionId, decisionSourceTurnId: f.turnId,
        state: 'sent', owner: 'exact-retained-helper', conversationId: null, createdAt: at - 100,
        sendAuthorizedAt: at - 20, deliveredAt: at - 10, messageId: randomUUID() },
      { id: outgoingId, sessionId: f.sessionId, text: 'Continue the exact original authorized work.', mode: 'after-turn',
        dueAt: 0, model: null, reasoningEffort: null, state: 'queued', owner: null, conversationId: f.conversationId,
        createdAt: at, sourceHelperId: helperId, sourceHelperAcceptedAt: before.acceptedAt }
    ];
    if (custody === 'withdrawn') Object.assign(rows[1]!, { state: 'failed',
      recoveryWithdrawAttempts: 4, recoveryWithdrawnSince: at, error: 'Automatic Continue was not sent: app-refused' });
    await (await import('../src/main/durable.js')).writeDurableNow('session-input', rows);
