      expect(goalPendingReplyFor(f.conversationId)).toEqual(pending);
      expect(await readEvents(f.sessionId, { kinds: ['tool_call'] })).toEqual([]);
      await saveConfig({ ...getConfig(), goal: { ...getConfig().goal, continuationPolicy: 'settled-turn' } });
