    let releaseFailure: ((ready: boolean) => void) | undefined;
    if (failureTiming === 'after') {
      goal.configureLoopForwardReadiness(() => new Promise<boolean>(resolve => { releaseFailure = resolve; }), settledForwardBridge.goalNativeCompletionReady);
      onTestFinished(() => { releaseFailure?.(false); goal.configureLoopForwardReadiness(settledForwardBridge.settledTurnContinuationAllowed, settledForwardBridge.goalNativeCompletionReady); });
    }
    goal.startGoalDraft({ sessionId: f.sessionId, conversationId: f.conversationId, turnId: f.turnId });
    if (failureTiming === 'before') await vi.waitFor(() => expect(goal.goalViewFor(f.conversationId)?.stage).toBe('failed'));
    else await vi.waitFor(() => expect(releaseFailure).toBeDefined());
    const oldToken = goal.goalViewFor(f.conversationId)!.token;
    const userId = randomUUID(), finalId = randomUUID(), turnId = 'exact-followup-after-failed-helper';
    await setSecret('openRouterApiKey', 'test-new-source-owner-key');
