  async function knownCurrentQuestionWithOrphan(mode: 'goal' | 'loop' = 'loop') {
    const f = await settledFixture();
    await setGoalSwitchNow(f.conversationId, mode, true);
    const input = await import('../src/main/session/input.js');
    const at = Date.now();
    const orphan = { id: randomUUID(), sessionId: null, conversationId: null, projectId: null,
      text: 'Start the older unrelated fresh-chat task.', deliveryText: 'Frozen older fresh-chat body.',
      mode: 'auto' as const, transportIntent: 'browser' as const, dueAt: at - 3000,
      model: 'gpt-6-thinking', reasoningEffort: 'high' as const, state: 'cancelled' as const,
      owner: 'old-fresh-home-document', requiresAuthorization: true,
      operatorRequestKey: 'a'.repeat(64), createdAt: at - 3000, offeredAt: at - 2000, sendAuthorizedAt: at - 1000 };
    await writeDurableNow('session-input', [orphan]); input.resetInputForTests();
    input.configureInputDelivery({ applyAutomation: async () => {}, changed: () => {},
      recordDelivered: (await import('../src/main/session/input-history.js')).recordDeliveredInput,
      settledTurnForwardReadiness: settledForwardBridge.settledTurnInputForwardProof });
    onTestFinished(async () => {
      (await import('../src/main/goal.js')).retireGoalDraftsFor(f.conversationId);
      for (const row of await input.listInputs()) await input.cancelInput(row.id);
      input.resetInputForTests(); await writeDurableNow('session-input', []);
    });
    const known = await input.enqueueInput({ id: randomUUID(), sessionId: f.sessionId, text: 'Continue this existing task from verified saved effects; never replay uncertain actions.',
      mode: 'auto', dueAt: 0, model: 'gpt-6-thinking', reasoningEffort: 'high' });
    const claimed = await input.claimBrowserInput(known.id, 'current-known-native-owner', f.conversationId, true);
    expect(claimed).not.toBeNull();
    expect(await input.authorizeBrowserInput(known.id, 'current-known-native-owner', f.conversationId)).toBe(true);
    const userId = randomUUID(), finalId = randomUUID(), turnId = 'known-current-' + randomUUID();
    expect(await input.acknowledgeBrowserInput(known.id, 'current-known-native-owner', f.conversationId, userId)).toBe(true);
    await request('POST', '/events', { body: { conversationId: f.conversationId, events: [
      { kind: 'user_message', messageId: userId, text: claimed!.text, time: Date.now() },
      { kind: 'turn_start', turnId, time: Date.now() },
      { kind: 'assistant_message', messageId: finalId, providerMessageId: finalId, turnId,
        text: 'New useful work is saved; the older uncertain Send remains unverified.', state: 'final', final: true, time: Date.now() },
      { kind: 'turn_end', turnId, outcome: 'completed', time: Date.now() }
    ] } });
    await acceptGoalReplyNow({ conversationId: f.conversationId, sessionId: f.sessionId,
      replyId: finalId, turnId, eventSeq: (await readEvents(f.sessionId, { kinds: ['assistant_message'] })).at(-1)!.seq, blocked: false });
    Object.assign(f.diagnostic.ordinaryFinal, { sourceUserMessageId: userId, settledFinalMessageId: finalId,
      coreCallMessageIds: ['current-source-unverified-core-call'] });
    await request('POST', `/activity?conversationId=${f.conversationId}`, {
      body: { coreDiagnostic: { ...f.diagnostic, observedAt: Date.now() }, observationOnly: true }
    });
    return { ...f, input, orphan, known, userId, finalId, turnId };
  }

