      if (reason === 'old-row-bound-to-target') old.conversationId = f.conversationId;
      if (reason === 'missing-new-chat-intent') old.operatorRequestKey = undefined;
      if (reason === 'missing-frozen-body') old.deliveryText = undefined;
      if (reason === 'helper-intent') { old.purpose = 'decision'; old.lifetime = 'temporary-planner'; }
      if (reason === 'same-document') old.owner = known.owner;
      if (reason === 'late-authorization') old.sendAuthorizedAt = known.createdAt + 1;
