  it('coalesces only the identical in-flight conversation and accepts a fresh click immediately after completion', async () => {
    await pair();
    const firstConversation = 'a055e101-1111-4111-8111-000000000102';
    const secondConversation = 'a055e101-1111-4111-8111-000000000103';
    const first = requestBrowserConversationOpen(firstConversation);
    const duplicate = requestBrowserConversationOpen(firstConversation);
    const other = requestBrowserConversationOpen(secondConversation);
    expect(duplicate).toBe(first);
    expect(other).not.toBe(first);

    const publications = (await request('GET', '/status')).body.openConversationRequests;
    expect(publications).toHaveLength(2);
    const acknowledge = async (publication: any) => request('POST', '/browser/open-chat', { body: {
      conversationId: publication.conversationId,
      requestId: publication.requestId,
      nonce: publication.nonce,
      outcome: 'focused',
      timing: {
        deliveredAt: 1,
        inventoryStartedAt: 2,
        inventoryCompletedAt: 3,
        exactMatchAt: 4,
        actionStartedAt: 5,
        actionCompletedAt: 6,
        acknowledgementStartedAt: 7
      }
    } });
    for (const publication of publications) expect((await acknowledge(publication)).status).toBe(200);
    await expect(first).resolves.toMatchObject({ ok: true, conversationId: firstConversation });
    await expect(other).resolves.toMatchObject({ ok: true, conversationId: secondConversation });

    const again = requestBrowserConversationOpen(firstConversation);
    const fresh = (await request('GET', '/status')).body.openConversationRequests;
    expect(fresh).toHaveLength(1);
    expect(fresh[0].requestId).not.toBe(publications.find((row: any) => row.conversationId === firstConversation)?.requestId);
    expect((await acknowledge(fresh[0])).status).toBe(200);
    await expect(again).resolves.toMatchObject({ ok: true, conversationId: firstConversation });
  });

  describe('exhausted named-conversation route recovery', () => {
    const notice = (conversationId: string, nonce: string, requestId = 'unreachable-request-1',
      requestNonce?: string) => request('POST', '/browser/unreachable-conversation', { body: {
        conversationId, requestId, nonce, ...(requestNonce ? { requestNonce } : {})
      } });

    it('creates one durable continuation, preserves its named Loop context, and deduplicates the episode nonce', async () => {
      await pair();
      const from = 'a055e101-1111-4111-8111-000000000141';
      const recorded = await request('POST', '/events', { body: { conversationId: from, events: [
        { kind: 'user_message', time: Date.now(), messageId: 'unreachable-opening',
          text: 'Finish the named project without losing its state.' }
      ] } });
      const sessionId = recorded.body.sessionId as string;
      await renameSession(sessionId, 'My durable nickname');
      await bindSessionProject(sessionId, '11111111-1111-4111-8111-000000000141');
      await setGoalObjectiveNow(from, 'Keep auditing and fixing the project');
      await setGoalSwitchNow(from, 'loop', true);
      const nonce = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaa0141';

      const first = await notice(from, nonce);
      expect(first.status).toBe(200);
      expect(first.body).toMatchObject({ accepted: true, conversationId: from, nonce,
        token: expect.any(String), commandId: expect.any(String) });
      const duplicate = await notice(from, nonce);
      expect(duplicate.status).toBe(200);
      expect(duplicate.body).toEqual(first.body);
      await waitForOpened(1);
      expect(new URL(opened[0]!).searchParams.get('clf')).toBe(first.body.commandId);

      const continuation = continuationForSession(sessionId);
      expect(continuation).toMatchObject({ token: first.body.token, from, state: 'awaiting-chat', automatic: true });
      expect((await getSession(sessionId))?.title).toBe('My durable nickname');
      expect((await getSession(sessionId))?.projectId).toBe('11111111-1111-4111-8111-000000000141');
      expect(goalObjectiveFor(from)).toBe('Keep auditing and fixing the project');
      expect(goalSwitchFor(from)).toMatchObject({ enabled: true, mode: 'loop' });
      const handoff = await readHandoff(sessionId, continuation!.handoffId!);
      expect(handoff?.text).toContain('UNREACHABLE-CONVERSATION HANDOFF');
      expect(handoff?.text).toContain('My durable nickname');
      expect(handoff?.text).toContain('Keep auditing and fixing the project');

      const to = 'a055e101-1111-4111-8111-000000000142';
      expect(await claimContinuationNow(first.body.token, to)).not.toBeNull();
      expect(await commitContinuation(first.body.token, to)).toBe(true);
      expect((await getSession(sessionId))?.conversationId).toBe(to);
      expect((await getSession(sessionId))?.title).toBe('My durable nickname');
      expect((await getSession(sessionId))?.projectId).toBe('11111111-1111-4111-8111-000000000141');
      // A response lost between main and extension is acknowledged from the durable A→B fence,
      // rather than polling the now-unbound source forever or creating another continuation.
      const late = await notice(from, 'bbbbbbbbbbbbbbbbbbbbbbbbbbbb0141', 'unreachable-request-late');
      expect(late.status).toBe(200);
      expect(late.body).toMatchObject({ accepted: true, reason: 'already_continued' });
    });

    it('reuses the exact pending continuation and command instead of reconstructing either', async () => {
      await pair();
      const from = 'a055e101-1111-4111-8111-000000000143';
      const recorded = await request('POST', '/events', { body: { conversationId: from, events: [
        { kind: 'user_message', time: Date.now(), messageId: 'reuse-opening', text: 'Continue this loop.' }
      ] } });
      const sessionId = recorded.body.sessionId as string;
      await setGoalSwitchNow(from, 'loop', true);
      const existing = await openContinuationNow(sessionId, from, true);
      expect(await attachSummary(existing.token, SAMPLE_BRIEF)).not.toBeNull();
      const command = queueResume(sessionId, existing.token)!;
      await waitForOpened(1);

      const reply = await notice(from, 'cccccccccccccccccccccccccccc0143');
      expect(reply.status).toBe(200);
      expect(reply.body).toMatchObject({ accepted: true, token: existing.token, commandId: command.id });
      expect(continuationForSession(sessionId)?.token).toBe(existing.token);
      expect(opened).toHaveLength(1);
      expect(new URL(opened[0]!).searchParams.get('clf')).toBe(command.id);
    });

    it.each(['no-intent', 'worker', 'active', 'tool', 'ambiguous-input', 'blocked'] as const)(
      'refuses unsafe %s recovery without creating a continuation', async kind => {
        await pair();
        const suffix = ['no-intent', 'worker', 'active', 'tool', 'ambiguous-input', 'blocked'].indexOf(kind) + 1;
        const chat = `a055e101-1111-4111-8111-00000000015${suffix}`;
        if (kind === 'worker') {
          await noteChatOrigin(chat, { kind: 'worker', fromSessionId: null, agentId: 'worker-1', task: 'unsafe worker' });
        }
        const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
          { kind: 'user_message', time: Date.now(), messageId: `unsafe-${kind}`, text: 'Do not move this unsafely.' },
          ...(kind === 'active' ? [{ kind: 'turn_start', time: Date.now(), turnId: 'unsafe-active-turn' }] : [])
        ] } });
        const sessionId = recorded.body.sessionId as string;
        if (kind !== 'no-intent') await setGoalSwitchNow(chat, 'loop', true);
        if (kind === 'blocked') setChatBlocked(chat, true);

        let releaseTool: (() => void) | null = null;
        let heldTool: Promise<void> | null = null;
        if (kind === 'tool') {
          const calls = await import('../src/main/mcp/call-context.js');
          heldTool = calls.trackInFlight({ startedAt: Date.now(), transportKey: null, agent: null,
            caller: { transportKey: null, requestId: 'unsafe-tool-request', conversationId: chat, sessionId },
            outcome: null, evidence: calls.emptyEvidence() }, () => new Promise<void>(resolve => { releaseTool = resolve; }));
          await Promise.resolve();
        }
        const input = await import('../src/main/session/input.js');
        if (kind === 'ambiguous-input') {
          const row = await input.enqueueInput({ id: randomUUID(), sessionId, text: 'Pending explicit correction',
            mode: 'auto', dueAt: Date.now(), model: null, reasoningEffort: null });
          expect(await input.claimBrowserInput(row.id, 'unreachable-owner', chat, true)).toMatchObject({
            id: row.id, state: 'browser', owner: 'unreachable-owner', conversationId: chat,
            requiresAuthorization: true
          });
        }
        try {
          const reply = await notice(chat, `dddddddddddddddddddddddddddd015${suffix}`);
          expect(reply.status).toBe(409);
          expect(reply.body).toMatchObject({ accepted: false, reason: 'recovery_not_safe' });
          expect(continuationForSession(sessionId)).toBeNull();
        } finally {
          if (heldTool) {
            (releaseTool as unknown as () => void)();
            await heldTool;
          }
          if (kind === 'blocked') setChatBlocked(chat, false);
          if (kind === 'ambiguous-input') {
            await writeDurableNow('session-input', []);
            input.resetInputForTests();
          }
        }
      }
    );

    it('rechecks safety before reusing an awaiting-chat continuation and permits a later nonce retry', async () => {
      await pair();
      const chat = 'a055e101-1111-4111-8111-000000000161';
      const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
        { kind: 'user_message', time: Date.now(), messageId: 'reuse-race-opening', text: 'Continue safely.' }
      ] } });
      const sessionId = recorded.body.sessionId as string;
      await setGoalSwitchNow(chat, 'loop', true);
      const continuation = await openContinuationNow(sessionId, chat, true);
      expect(await attachSummary(continuation.token, SAMPLE_BRIEF)).not.toBeNull();

      const input = await import('../src/main/session/input.js');
      const originalList = input.listInputs;
      let reads = 0;
      let reachedSecond!: () => void;
      let releaseSecond!: () => void;
      const second = new Promise<void>(resolve => { reachedSecond = resolve; });
      const release = new Promise<void>(resolve => { releaseSecond = resolve; });
      const spy = vi.spyOn(input, 'listInputs').mockImplementation(async () => {
        reads += 1;
        if (reads === 3) { reachedSecond(); await release; }
        return originalList();
      });
      try {
        const first = notice(chat, 'eeeeeeeeeeeeeeeeeeeeeeeeeeee0161');
        await second;
        setChatBlocked(chat, true);
        releaseSecond();
        const refused = await first;
        expect(refused.status).toBe(409);
        expect(refused.body).toMatchObject({ accepted: false, reason: 'recovery_raced' });
        expect(pendingCommands().filter(command => command.what === `resume:${continuation.token}`)).toEqual([]);

        setChatBlocked(chat, false);
        const retried = await notice(chat, 'eeeeeeeeeeeeeeeeeeeeeeeeeeee0161');
        expect(retried.status).toBe(200);
        expect(retried.body).toMatchObject({ accepted: true, token: continuation.token });
      } finally {
        spy.mockRestore();
        setChatBlocked(chat, false);
      }
    });
  });

