  it('holds the exact saved Loop obligation until a late native Core result reaches durable Main and then admits its real existing Goal draft owner', async () => {
    const { sessionId } = await setup();
    await saveConfig({ ...getConfig(), goal: { ...getConfig().goal, loopBackend: 'chatgpt' } });
    resetCoreBrowserEvidenceForTests();
    const requestId = 'wfr_ordinary_loop_late_native_result';
    const pageMessageId = 'native-page-core-request';
    const open = { documentId: 'saved-loop-native-page', navigationEpoch: 3, observedAt: Date.now(),
      shell: 'alternate', shellDiscovery: 'compatible', requestIds: [requestId], turnId: null,
      ordinaryFinal: { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
        codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
        sourceUserMessageId: userId, coreCallMessageIds: [pageMessageId],
        allCoreRequestIds: [requestId], openRequestIds: [requestId] } };
    const report = (final: Record<string, unknown>) => request('GET',
      `/activity?conversationId=${chat}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
        ...open, observedAt: Date.now(), ordinaryFinal: final
      }))}`);
    try {
      // The tool was DISPATCHED before the native final, even though its
      // durable result lands later. A newly started post-final Core call
      // correctly invalidates this final and must not be used as the fixture.
      const originalToolStartedAt = Date.now() - 1_000;
      expect((await request('POST', '/events', { body: { conversationId: chat,
        events: [terminal()] } })).status).toBe(200);
      const pending = goalPendingReplyFor(chat)!;
      expect(pending).toMatchObject({ sessionId, replyId: finalId });
      expect((await report(open.ordinaryFinal)).status).toBe(200);
      const body = { conversationId: chat, turnId: pending.turnId, clientId: 'verified-late-loop-owner', terminalRequired: true };
      expect((await request('POST', '/goal/draft', { body })).body.error).toBe('native_completion_unverified');
      const owner = await request('POST', '/correlations', { body: { conversationId: chat,
        calls: [{ messageId: pageMessageId, requestId, tool: 'read', answered: false }] } });
      expect(owner.body).toMatchObject({ complete: true, confirmed: [requestId], sessionId });
      const final = { ...open.ordinaryFinal, reason: 'associated', openCalls: 0, openRequestIds: [] };
      expect((await report(final)).status).toBe(200);
      expect((await request('POST', '/goal/draft', { body })).body.error).toBe('native_completion_unverified');
      await recordToolCall({ tool: 'read', args: { paths: ['/project/late-core-result.txt'] },
        content: [{ type: 'text', text: 'The original Core call returned.' }],
        durationMs: 1, outcome: 'ok', startedAt: originalToolStartedAt, requestId });
      // An already-observed validated native final can outlive its Core result
      // publication. The existing session/Work status owner must also clear
      // its obsolete "waiting for evidence" projection as soon as the exact
      // durable receipt exists, without demanding another browser Fiber scan,
      // extension activity poll, or speculative /goal/draft claim.
      const status = await sessionControlsFor(sessionId);
      expect(status.goalWait?.reason).not.toBe('evidence');
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(chat))).toBeNull();
      // A real subsequent Goal draft request still owns all independent Send
      // admission/quiet checks, and may spend only this pending obligation.
      const admitted = await request('POST', '/goal/draft', { body });
      expect(admitted.body.error).not.toBe('native_completion_unverified');
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(chat))).toBeNull();
      if (admitted.status === 409) {
        // A legitimate independent quiet window may be active depending on
        // when the original provider start was recorded. Never bypass it:
        // exercise the existing expiration through test time only.
        const controls = await sessionControlsFor(sessionId);
        expect(admitted.body.error).toBe('chat_still_working');
        expect(controls.goalWait).toMatchObject({ reason: 'quiet', until: expect.any(Number) });
        const restoredClock = vi.spyOn(Date, 'now').mockReturnValue((controls.goalWait?.until ?? Date.now()) + 1);
        try {
          const ready = await request('POST', '/goal/draft', { body });
          expect(ready.status, JSON.stringify(ready.body)).toBe(200);
        } finally { restoredClock.mockRestore(); }
      } else {
        expect(admitted.status, JSON.stringify(admitted.body)).toBe(200);
      }
      expect(goalPendingReplyFor(chat)?.replyId).toBe(finalId);
    } finally {
      resetCoreBrowserEvidenceForTests();
    }
  });

