  it.each(['queued', 'claimed', 'native-send-unconfirmed'] as const)(
    'withholds the exact saved automatic continuation after a manual close (%s), preserving its receipt custody', async phase => {
      const { input, sessionId } = await setup();
      await request('POST', '/events', { body: { conversationId: chat, events: [terminal()] } });
      const pending = goalPendingReplyFor(chat)!;
      const controller = new AbortController();
      const decision = input.requestBrowserDecision('Choose the exact next step.', controller.signal, {
        lifetime: 'temporary-planner', sourceSessionId: sessionId, sourceTurnId: pending.turnId,
        onAccepted: () => ({ sessionId, conversationId: chat, sourceTurnId: pending.turnId,
          sourceAcceptedAt: pending.acceptedAt, text: 'Continue only the saved objective.' })
      });
      try {
        const helper = (await input.listInputs()).find(entry => entry.purpose === 'decision')!;
        expect(await input.claimBrowserInput(helper.id, 'closed-source-helper', null, true)).not.toBeNull();
        expect(await input.authorizeBrowserInput(helper.id, 'closed-source-helper', null)).toBe(true);
        expect(await input.acknowledgeBrowserInput(helper.id, 'closed-source-helper', null, randomUUID())).toBe(true);
        expect(await input.completeBrowserDecision(helper.id, 'closed-source-helper', 'Continue the saved work.')).toBe(true);
        await decision;
        const outgoing = (await input.listInputs()).find(entry => entry.sourceHelperId === helper.id)!;
        const owner = 'closed-source-page';
        if (phase !== 'queued') {
          expect((await request('POST', '/input/claim', { body: {
            id: outgoing.id, owner, conversationId: chat, requiresAuthorization: true
          } })).body.input).toMatchObject({ id: outgoing.id });
          if (phase === 'native-send-unconfirmed')
            expect((await request('POST', '/input/claim', { body: {
              id: outgoing.id, owner, conversationId: chat, authorize: true
            } })).body.ok).toBe(true);
        }
        expect((await request('POST', '/closed', { body: { conversationId: chat, manual: true } })).status).toBe(200);
        const retained = (await input.listInputs()).find(entry => entry.id === outgoing.id)!;
        expect(retained).toMatchObject({ id: outgoing.id, text: outgoing.text, sourceHelperId: helper.id });
        const status = (await request('GET', '/status')).body;
        expect(status.inputs.some((entry: { id: string }) => entry.id === outgoing.id)).toBe(false);
        expect(status.inputOpeningIds).toContain(outgoing.id);
        expect((await request('POST', '/input/claim', { body: {
          id: outgoing.id, owner, conversationId: chat, requiresAuthorization: true
        } })).body.input).toBeNull();
        expect((await request('POST', '/input/claim', { body: {
          id: outgoing.id, owner, conversationId: chat, authorize: true
        } })).body.ok).toBe(false);
        if (phase === 'native-send-unconfirmed') {
          expect((await input.listInputs()).find(entry => entry.id === outgoing.id))
            .toMatchObject({ state: 'browser', owner, sendAuthorizedAt: retained.sendAuthorizedAt });
          // A close cannot undo or reject a native Send receipt from the original owner.
          const nativeMessageId = randomUUID();
          expect((await request('POST', '/input/ack', { body: {
            id: outgoing.id, owner, conversationId: chat, messageId: nativeMessageId
          } })).body.ok).toBe(true);
          expect((await input.listInputs()).find(entry => entry.id === outgoing.id))
            .toMatchObject({ state: 'sent', owner, messageId: nativeMessageId });
        } else {
          expect((await input.listInputs()).find(entry => entry.id === outgoing.id)?.sendAuthorizedAt).toBeUndefined();
          // Only the existing exact successful Open owner releases this close fence.
          const opening = requestBrowserConversationOpen(chat);
          const publication = (await request('GET', '/status')).body.openConversationRequests[0];
          expect((await request('POST', '/browser/open-chat', { body: {
            conversationId: chat, requestId: publication.requestId, nonce: publication.nonce, outcome: 'opened',
            timing: { deliveredAt: 1, inventoryStartedAt: 2, inventoryCompletedAt: 3, exactMatchAt: 4,
              actionStartedAt: 5, actionCompletedAt: 6, acknowledgementStartedAt: 7 }
          } })).status).toBe(200);
          await expect(opening).resolves.toMatchObject({ ok: true });
          expect((await request('GET', '/status')).body.inputs)
            .toContainEqual(expect.objectContaining({ id: outgoing.id, conversationId: chat }));
        }
      } finally { controller.abort(); await decision.catch(() => undefined); }
    }
  );

