    const checkpointKey = variant === 'matching-key' ? originalKey
      : variant === 'different-key' ? randomBytes(32).toString('hex') : undefined;
    if (variant === 'different-key') expect(checkpointKey).not.toBe(originalKey);
    await f.logger.noteLocalIncident({ source: 'browser-debug', reason: 'native_terminal_open_call',
      sessionId: f.sessionId, conversationId: f.conversationId, nativeCompletion: {
        ...counts, ...(checkpointKey === undefined ? {} : { checkpointKey })
      } });
    expect((await f.logger.listLocalIncidents()).incidents).toContainEqual(expect.objectContaining({
      conversationId: f.conversationId, status: 'unresolved',
      nativeCompletion: expect.objectContaining({ ...counts,
        ...(checkpointKey === undefined ? {} : { checkpointKey }) })
    }));
    await f.restart();
    const restored = coreBrowserEvidence(f.conversationId)?.pendingCompletion;
    expect(restored).toMatchObject({
      documentId: f.expected.documentId, navigationEpoch: f.expected.navigationEpoch,
      observedAt: f.expected.observedAt, sourceUserMessageId: f.userId,
      coreCallMessageIds: f.expected.coreCallMessageIds, allCoreRequestIds: f.expected.allCoreRequestIds,
      openRequestIds: f.expected.openRequestIds,
      reason: variant === 'matching-key' ? 'open-call' : 'inventory-incomplete'
    });
    // Extra diagnostic debt cannot rewrite A's private original into guessed parents.
    expect(await sessionStoreModule.readSessionNativeCompletionFence(
      f.sessionId, f.conversationId, f.profileId)).toEqual(f.expected);
    expect(nativeFinalEvidenceWait(coreBrowserEvidence(f.conversationId))?.reason).toBe('evidence');
    expect(nativeCompletionCandidate(f.conversationId)).toBeNull();
