  it.each(['source', 'census'] as const)(
    'retains the latest private native completion custody when %s changes after the durable clear await', async changed => {
    const f = await privateNativeCheckpointFixture();
    expect(await sessionStoreModule.readSessionNativeCompletionFence(
      f.sessionId, f.conversationId, f.profileId)).toEqual(f.expected);
    await f.returned();
    const write = sessionStoreModule.compareAndSetSessionNativeCompletionFence;
    let release!: () => void, entered!: () => void, heldOnce = false;
    const hold = new Promise<void>(resolve => { release = resolve; });
    const boundary = new Promise<void>(resolve => { entered = resolve; });
    const writer = vi.spyOn(sessionStoreModule, 'compareAndSetSessionNativeCompletionFence')
      .mockImplementation(async (...args) => {
        const result = await write(...args);
        if (!heldOnce && args[3] !== null && args[4] === null) {
          heldOnce = true;
          entered();
          await hold;
        }
        return result;
      });
    const reporting = f.report(f.associated());
    try {
      await Promise.race([boundary, reporting.then(() => {
        throw new Error('Native completion returned without awaiting its private clear owner');
      })]);
      const userId = changed === 'source' ? randomUUID() : f.userId;
      const nativeId = 'new-native-' + randomUUID(), requestId = 'wfr_new_' + randomUUID().replaceAll('-', '');
      if (changed === 'source') {
        await appendEvent(f.sessionId, { kind: 'user_message', source: 'extension',
          time: Date.now(), messageId: userId,
          message: { text: 'A genuinely newer human instruction.', chars: 35, truncated: false } });
        await appendEvent(f.sessionId, { kind: 'turn_start', source: 'extension',
          time: Date.now(), turnId: 'new-native-turn-' + randomUUID() });
      }
      const ordinaryFinal = { ...f.diagnostic.ordinaryFinal, sourceUserMessageId: userId,
        calls: changed === 'source' ? 1 : 2, openCalls: 1,
        coreCallMessageIds: changed === 'source' ? [nativeId] : [f.nativeId, nativeId],
        allCoreRequestIds: changed === 'source' ? [requestId] : [f.requestId, requestId],
        openRequestIds: [requestId] };
      expect((await import('../src/main/core-browser-evidence.js')).noteCoreBrowserEvidence({
        ...f.diagnostic, conversationId: f.conversationId, observedAt: Date.now(),
        ordinaryFinal, requestIds: [], turnId: null
      } as any)).toBe(true);
      const latest = structuredClone(coreBrowserEvidence(f.conversationId)!.pendingCompletion);
      expect(latest).toMatchObject({ sourceUserMessageId: userId,
        coreCallMessageIds: ordinaryFinal.coreCallMessageIds, openRequestIds: [requestId] });
      release();
      await reporting;
      expect(heldOnce).toBe(true);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(f.conversationId))?.reason).toBe('evidence');
      expect(settledForwardBridge.goalNativeCompletionReady(f.conversationId)).toBe(false);
      const durable = await sessionStoreModule.readSessionNativeCompletionFence(
        f.sessionId, f.conversationId, f.profileId);
      expect(durable).toMatchObject(latest!);
      expect((await readEvents(f.sessionId, { kinds: ['tool_call'] })).filter(row => row.kind === 'tool_call' &&
        row.call.requestId === f.requestId)).toHaveLength(1);
      await f.restart();
      expect(coreBrowserEvidence(f.conversationId)?.pendingCompletion).toEqual(latest);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(f.conversationId))?.reason).toBe('evidence');
    } finally {
      release();
      await reporting.catch(() => undefined);
      writer.mockRestore();
    }
  });

  it.each([false, true])('restores an unresolved native-final incident into a fail-closed Loop fence before Bridge republishes on a process-style restart (masked legacy slot: %s)', async withMaskedLegacySlot => {
    const logger = await import('../src/main/logger.js');
    const profileId = (await import('../src/main/config.js')).getActiveInstanceRuntime().profile.id;
    logger.setLogProfileContext(profileId);
    logger.initLogFile(path.join(dir,
      withMaskedLegacySlot ? 'native-completion-restart-masked' : 'native-completion-restart-clean', 'app.log'));
    const conversationId = randomUUID();
    const sourceUserMessageId = 'fefefefe-1111-4111-8111-222222222222';
    let stopped = false;
    try {
      await pair(); resetCoreBrowserEvidenceForTests();
      const start = await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'user_message', time: Date.now(), messageId: sourceUserMessageId,
          text: 'Do not replay this after restart.' }
      ] } });
      expect(start.status).toBe(200);
      const initial = { documentId: 'incident-browser-before-restart', navigationEpoch: 4,
        observedAt: Date.now(), shell: 'alternate', shellDiscovery: 'compatible',
        ordinaryFinal: { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
          codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
          sourceUserMessageId, openRequestIds: [] } };
      // A real legacy incident has counts only; never publish a modern identity-bearing frame first.
      expect(await sessionStoreModule.readSessionNativeCompletionFenceCheckpoint(
        start.body.sessionId, conversationId, profileId)).toBeNull();
      await logger.noteLocalIncident({ source: 'browser-debug', reason: 'native_terminal_open_call',
        sessionId: start.body.sessionId, conversationId, capture: 'not_requested',
        nativeCompletion: { openCalls: 1, openCodeCalls: 0, traceRequestIds: 0, exactRequestJoins: 0 } });
      await logger.flushLocalIncidents();
      expect((await logger.listLocalIncidents()).incidents).toContainEqual(expect.objectContaining({
        conversationId, sessionId: start.body.sessionId, status: 'unresolved',
        reason: 'native_terminal_open_call' }));
      if (withMaskedLegacySlot) {
        const owned = await logger.listLocalIncidents();
        expect(owned.status).toBe('ready');
        const source = JSON.parse(await fs.readFile(path.join(owned.folder!, 'incident-0.json'), 'utf8'));
        // A legacy mask is occupied evidence that cannot be adopted or erased.
        // It must not suppress the independent, verified current-account fence.
        const masked = { ...source, id: randomUUID(), profileId: '***' };
        const held = path.join(owned.folder!, 'incident-15.json');
        await fs.writeFile(held, JSON.stringify(masked), { flag: 'wx' });
        expect(await logger.listLocalIncidents()).toMatchObject({
          status: 'storage_unavailable', storageError: 'incident_slot_unverified',
          unverifiedSlots: 1, incidents: [expect.objectContaining({ conversationId })]
        });
        expect(await fs.readFile(held, 'utf8')).toBe(JSON.stringify(masked));
      }
      // Fill the hot ring with ordinary diagnostics before the real Bridge restart.
      // Preserving an archive alone must never remove a fail-closed native-completion fence.
      const fenceBeforePressure = (await logger.listLocalIncidents()).incidents.find(row =>
        row.conversationId === conversationId && row.reason === 'native_terminal_open_call');
      expect(fenceBeforePressure).toBeDefined();
      for (let pressure = 0; pressure < 33; pressure++) {
        await logger.noteLocalIncident({ source: 'app', reason: `restart_archive_pressure_${pressure}` });
      }
      await logger.flushLocalIncidents();
      const pressuredIncidents = await logger.listLocalIncidents();
      expect(pressuredIncidents.archive?.count ?? 0).toBeGreaterThan(0);
      expect(pressuredIncidents.incidents).toContainEqual(fenceBeforePressure);
      await stopBridge(); stopped = true;
      await flushSessions();
      resetSessionStoreForTests();
      resetCoreBrowserEvidenceForTests(); // the old Main process-local caches are gone
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))).toBeNull();
      const rebound = await startBridge();
      expect(rebound).not.toBeNull(); stopped = false;
      base = `http://127.0.0.1:${rebound}`;
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
      expect(await sessionStoreModule.readSessionNativeCompletionFenceCheckpoint(
        start.body.sessionId, conversationId, profileId)).toBeNull();
      expect(coreBrowserEvidence(conversationId)?.pendingCompletion).toMatchObject({
        sourceUserMessageId: null, openRequestIds: null });
      await pair();
      const newDocument = { ...initial, documentId: 'after-restart-document', navigationEpoch: 0,
        observedAt: Date.now(), ordinaryFinal: { ...initial.ordinaryFinal, reason: 'associated',
          openCalls: 0, openRequestIds: [], sourceUserMessageId } };
      expect((await request('GET', `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify(newDocument))}`)).status).toBe(200);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
      // Renderer/Work status now opportunistically reconciles exact late
      // completions. After restart the restored incident has NO original
      // native tool-message/request identity, so a visible new final must
      // remain fail-closed even when that status reader is exercised.
      expect((await sessionControlsFor(start.body.sessionId)).sessionId).toBe(start.body.sessionId);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
      expect((await logger.listLocalIncidents()).incidents).toContainEqual(expect.objectContaining({
        conversationId, status: 'unresolved' }));
    } finally {
      if (stopped) {
        const recovered = await startBridge();
        if (recovered) base = `http://127.0.0.1:${recovered}`;
      }
      await logger.flushLocalIncidents();
      await logger.flushLogFile();
      logger.resetLoggerForTests();
      resetCoreBrowserEvidenceForTests();
    }
  });

