  it('rejects a stale same-conversation request-id epoch in real authenticated Core /correlations without confirming that newer native turn', async () => {
    const conversationId = randomUUID();
    const requestId = 'wfr_native_previous_session_epoch';
    const previousSession = '2026-10-15-old-epoch';
    await pair();
    const opened = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'user_message', messageId: randomUUID(), text: 'One current authorized turn.', time: Date.now() },
      { kind: 'turn_start', turnId: 'g-current-epoch-turn', time: Date.now() + 1 }
    ] } });
    expect(opened.status).toBe(200);
    const currentSession = opened.body.sessionId as string;
    expect(currentSession).not.toBe(previousSession);
    const observedAt = Date.now() - 1000;
    expect(observeRequestCorrelation({
      requestId, conversationId, sessionId: previousSession, messageId: 'previous-epoch-call',
      tool: 'read', observedAt
    })).toBe('stored');

    // A current native page reporting the old workflow id cannot turn that
    // original session's authenticated tool result into this newer epoch's work.
    const stale = await request('POST', '/correlations', { body: { conversationId,
      turnId: 'g-current-epoch-turn',
      calls: [{ messageId: 'current-epoch-call', requestId, tool: 'read', order: 0, answered: false }]
    } });
    expect(stale.status).toBe(200);
    expect(stale.body).toMatchObject({
      sessionId: currentSession, confirmed: [], confirmedTurnIds: [],
      conflicts: [requestId], complete: false
    });
    expect(requestCorrelation(requestId)).toMatchObject({
      conversationId, sessionId: previousSession, messageId: 'previous-epoch-call', observedAt
    });

    // A genuinely new request id from this exact current session is accepted.
    const fresh = 'wfr_native_current_epoch';
    const accepted = await request('POST', '/correlations', { body: { conversationId,
      turnId: 'g-current-epoch-turn',
      calls: [{ messageId: 'verified-current-epoch-call', requestId: fresh, tool: 'read', order: 0, answered: false }]
    } });
    expect(accepted.body).toMatchObject({
      sessionId: currentSession, confirmed: [fresh], confirmedTurnIds: [fresh],
      conflicts: [], complete: true
    });
    expect(requestCorrelation(fresh)).toMatchObject({
      sessionId: currentSession, conversationId, turnId: 'g-current-epoch-turn'
    });
    // Delayed and duplicate browser ownership callbacks cannot upgrade the
    // prior session's request after the current native call has been accepted.
    for (let attempt = 0; attempt < 2; attempt++) {
      const duplicate = await request('POST', '/correlations', { body: { conversationId,
        turnId: 'g-current-epoch-turn',
        calls: [{ messageId: 'current-epoch-call', requestId, tool: 'read', order: 0, answered: false }]
      } });
      expect(duplicate.body).toMatchObject({
        sessionId: currentSession, confirmed: [], confirmedTurnIds: [],
        conflicts: [requestId], complete: false
      });
    }
    expect(requestCorrelation(requestId)).toMatchObject({
      sessionId: previousSession, messageId: 'previous-epoch-call', observedAt
    });
  });

  it.each(['ok', 'process_exit_nonzero', 'tool_rejected', 'tool_execution_error', 'tool_internal_error'] as const)(
    'binds and settles two exact owned Core receipts sharing one workflow without rewriting either original execution (%s)', async outcome => {
    const recorder = await import('../src/main/session/recorder.js');
    const store = await import('../src/main/session/store.js');
    const conversationId = randomUUID(), userId = randomUUID();
    const requestId = 'wfr_two_owned_native_receipts';
    const messageIds = [randomUUID(), randomUUID()];
    const receipts = [randomBytes(24).toString('hex'), randomBytes(24).toString('hex')];
    const native = { documentId: 'owned-two-call-document', navigationEpoch: 4,
      shell: 'alternate', shellDiscovery: 'compatible', requestIds: [requestId] };
    const pending = { reason: 'open-call', questions: 1, calls: 2, openCalls: 2,
      codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
      sourceUserMessageId: userId, coreCallMessageIds: messageIds,
      allCoreRequestIds: [requestId, requestId], openRequestIds: [requestId, requestId] };
    const report = (ordinaryFinal: Record<string, unknown>) => request('GET',
      `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
        ...native, observedAt: Date.now(), ordinaryFinal }))}`);
    await pair(); resetCoreBrowserEvidenceForTests();
    const opened = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'user_message', messageId: userId, text: 'Verify both distinct owned tool results.', time: Date.now() }
    ] } });
    const sessionId = opened.body.sessionId;
    const calls = messageIds.map((messageId, index) => ({ messageId, requestId,
      tool: 'read', order: index, answered: false }));
    await request('POST', '/correlations', { body: { conversationId, calls } });
    await report(pending);
    for (const [index, resultReceiptId] of receipts.entries()) {
      await recorder.recordToolCall({ tool: 'read', args: { paths: [`/project/result-${index}.txt`] },
        content: [{ type: 'text', text: `Distinct original result ${index}` }], resultReceiptId,
        requestId, conversationId, sessionId, outcome: index === 0 ? 'ok' : outcome, durationMs: 1, startedAt: Date.now() });
    }
    await recorder.flushRecorder();
    const journal = path.join(store.sessionsRoot(), sessionId, 'events.jsonl');
    const originalBytes = await fs.readFile(journal);
    const bound = await request('POST', '/correlations', { body: { conversationId,
      calls: calls.map((call, index) => ({ ...call, answered: true, resultReceiptId: receipts[index] })) } });
    expect(bound.body.confirmedResultReceipts).toEqual(receipts);
    expect(requestCorrelation(requestId)?.nativeCallAmbiguous).toBe(true);
    await report({ ...pending, reason: 'associated', openCalls: 0, openRequestIds: [] });
    await sessionControlsFor(sessionId);
    expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))).toBeNull();
    expect(await fs.readFile(journal)).toEqual(originalBytes);
    const recorded = (await store.readEvents(sessionId, { kinds: ['tool_call'], requireIntegrity: true }))
      .filter((row): row is Extract<SessionEvent, { kind: 'tool_call' }> => row.kind === 'tool_call');
    expect(recorded).toHaveLength(2);
    expect(recorded.map(row => row.call.outcome)).toEqual(['ok', outcome]);
    expect(recorded.map(row => [row.call.requestId, row.call.nativeCallMessageId, row.call.attributionMethod]))
      .toEqual(messageIds.map(id => [requestId, id, 'request_id']));
    expect((await store.getSession(sessionId))?.toolCalls).toBe(2);
  });

  it.each(['open-call', 'open-code'] as const)(
    'keeps a late incomplete census above an existing %s fence despite the known durable results', async reason => {
      const recorder = await import('../src/main/session/recorder.js');
      const evidence = await import('../src/main/core-browser-evidence.js');
      const conversationId = randomUUID(), userId = randomUUID(), nativeId = randomUUID();
      const codeId = randomUUID(), requestId = 'wfr_late_incomplete_' + reason;
      const resultReceiptId = randomBytes(24).toString('hex');
      const native = { documentId: 'late-incomplete-http-document', navigationEpoch: 3,
        shell: 'alternate', shellDiscovery: 'compatible', requestIds: [requestId] };
      const pending = { reason, questions: 1, calls: 1, openCalls: reason === 'open-call' ? 1 : 0,
        codeCalls: 1, openCodeCalls: reason === 'open-code' ? 1 : 0, activeTurnMapped: false,
        sourceUserMessageId: userId, coreCallMessageIds: [nativeId], allCoreRequestIds: [requestId],
        openRequestIds: reason === 'open-call' ? [requestId] : [], codeCallMessageIds: [codeId],
        openCodeCallMessageIds: reason === 'open-code' ? [codeId] : [],
        answeredCodeCallMessageIds: reason === 'open-code' ? [] : [codeId] };
      const final = { ...pending, reason: 'associated', openCalls: 0, openCodeCalls: 0,
        openRequestIds: [], openCodeCallMessageIds: [], answeredCodeCallMessageIds: [codeId] };
      let observedAt = Date.now();
      const report = (ordinaryFinal: Record<string, unknown>) => request('POST',
        `/activity?conversationId=${conversationId}`, { body: { coreDiagnostic: {
          ...native, observedAt: ++observedAt, ordinaryFinal } } });
      try {
        await pair(); resetCoreBrowserEvidenceForTests();
        const opened = await request('POST', '/events', { body: { conversationId, events: [
          { kind: 'user_message', messageId: userId, text: 'Preserve every original native result.', time: Date.now() }
        ] } });
        expect(opened.status).toBe(200);
        const sessionId = opened.body.sessionId;
        const call = { messageId: nativeId, requestId, tool: 'read', order: 0, answered: false };
        expect((await request('POST', '/correlations', { body: { conversationId, calls: [call] } })).body.confirmed)
          .toEqual([requestId]);
        await recorder.recordToolCall({ tool: 'read', args: { paths: ['/project/original-return.txt'] },
          content: [{ type: 'text', text: 'The known original result returned.' }], resultReceiptId,
          requestId, conversationId, sessionId, outcome: 'ok', durationMs: 1, startedAt: Date.now() });
        await recorder.flushRecorder();
        expect((await request('POST', '/correlations', { body: { conversationId,
          calls: [{ ...call, answered: true, resultReceiptId }] } })).body.confirmedResultReceipts).toEqual([resultReceiptId]);
        const originalRows = await readEvents(sessionId, { kinds: ['tool_call'], requireIntegrity: true });
        expect(originalRows).toHaveLength(1);

        // Independent controls: a foreign question stays held; exact known proof settles.
        expect((await report(pending)).status).toBe(200);
        expect((await report({ ...final, sourceUserMessageId: randomUUID() })).status).toBe(200);
        expect(settledForwardBridge.goalNativeCompletionReady(conversationId)).toBe(false);
        expect((await report(final)).status).toBe(200);
        expect(coreBrowserEvidence(conversationId)?.pendingCompletion).toBeNull();
        expect(settledForwardBridge.goalNativeCompletionReady(conversationId)).toBe(true);

        resetCoreBrowserEvidenceForTests();
        expect((await report(pending)).status).toBe(200);
        const originalFence = coreBrowserEvidence(conversationId)!.pendingCompletion!;
        expect((await report({ reason: 'turn-invalid', questions: 1, calls: 0, openCalls: 0,
          codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false, callInventoryComplete: false })).status).toBe(200);
        expect((await report(final)).status).toBe(200);
        await sessionControlsFor(sessionId);
        expect(coreBrowserEvidence(conversationId)?.pendingCompletion)
          .toEqual({ ...originalFence, reason: 'inventory-incomplete' });
        expect(evidence.nativeCompletionCandidate(conversationId)).toBeNull();
        expect(evidence.acknowledgeNativeCompletion(conversationId, observedAt,
          originalFence.observedAt, [requestId], [nativeId])).toBe(false);
        expect(settledForwardBridge.goalNativeCompletionReady(conversationId)).toBe(false);
        expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.detail).toContain('incomplete');
        await saveConfig({ ...getConfig(), goal: { ...getConfig().goal, loopBackend: 'chatgpt' } });
        await setSessionAutomation(sessionId, 'loop');
        const draft = await request('POST', '/goal/draft', { body: { conversationId,
          turnId: 'late-incomplete-native-turn', clientId: 'late-incomplete-native-owner' } });
        expect(draft).toMatchObject({ status: 409, body: { error: 'native_completion_unverified' } });
        expect(await readEvents(sessionId, { kinds: ['tool_call'], requireIntegrity: true })).toEqual(originalRows);
      } finally { resetCoreBrowserEvidenceForTests(); }
    }
  );

  it('does not settle a native Core call from its sibling result when two typed native messages share one authenticated workflow request', async () => {
    const logger = await import('../src/main/logger.js');
    logger.initLogFile(path.join(dir, 'native-shared-workflow-sibling-result', 'app.log'));
    const conversationId = randomUUID(), sourceUserMessageId = randomUUID();
    const requestId = 'wfr_two_visible_native_calls_one_workflow';
    const pendingCallMessageId = 'provider-original-unanswered-call';
    const siblingCallMessageId = 'provider-sibling-answered-call';
    const native = { documentId: 'one-native-document-shared-workflow', navigationEpoch: 4,
      shell: 'alternate', shellDiscovery: 'compatible', requestIds: [requestId],
      ordinaryFinal: { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
        codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
        sourceUserMessageId, coreCallMessageIds: [pendingCallMessageId],
        allCoreRequestIds: [requestId], openRequestIds: [requestId] } };
    const report = (ordinaryFinal: Record<string, unknown>) => request('GET',
      `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
        ...native, observedAt: Date.now(), ordinaryFinal
      }))}`);
    try {
      await pair(); resetCoreBrowserEvidenceForTests();
      const opened = await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'user_message', messageId: sourceUserMessageId,
          text: 'Finish this original native Core read.', time: Date.now() }
      ] } });
      expect(opened.status).toBe(200);
      expect((await request('POST', '/correlations', { body: { conversationId,
        calls: [{ messageId: pendingCallMessageId, requestId, tool: 'read', answered: false }]
      } })).body).toMatchObject({ complete: true, confirmed: [requestId] });
      await report(native.ordinaryFinal);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');

      // A second positively observed Core invocation shares the workflow ID.
      // Its durable result is NOT proof that the first native tool message returned.
      expect((await request('POST', '/correlations', { body: { conversationId,
        calls: [{ messageId: siblingCallMessageId, requestId, tool: 'read', answered: true }]
      } })).body).toMatchObject({ complete: true, confirmed: [requestId] });
      await recordToolCall({ tool: 'read', args: { paths: ['/project/sibling-only.txt'] },
        content: [{ type: 'text', text: 'Sibling result, original result still missing.' }],
        outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId });
      const calls = await readEvents(opened.body.sessionId, { kinds: ['tool_call'] });
      expect(calls).toHaveLength(1);
      expect(calls[0]).toMatchObject({ kind: 'tool_call',
        call: { requestId, attributionMethod: 'request_id', conversationId } });
      await report({ ...native.ordinaryFinal, reason: 'associated', openCalls: 0,
        openRequestIds: [] });
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
      expect((await sessionControlsFor(opened.body.sessionId)).sessionId).toBe(opened.body.sessionId);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
    } finally {
      await logger.flushLocalIncidents();
      await logger.flushLogFile();
      logger.resetLoggerForTests();
      resetCoreBrowserEvidenceForTests();
    }
  });

  it('does not erase a native-final hold when an older duplicate Core result falls beyond the bounded history tail', async () => {
    const conversationId = randomUUID(), userId = randomUUID();
    const requestId = 'wfr_duplicate_buried_native_result';
    const nativeCallId = 'original-exact-native-message-with-two-transport-returns';
    const original = { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
      codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
      sourceUserMessageId: userId, coreCallMessageIds: [nativeCallId],
      allCoreRequestIds: [requestId], openRequestIds: [requestId] };
    const native = { documentId: 'native-duplicate-outside-tail', navigationEpoch: 8,
      shell: 'alternate', shellDiscovery: 'compatible', requestIds: [requestId] };
    const report = (ordinaryFinal: Record<string, unknown>) => request('GET',
      `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
        ...native, observedAt: Date.now(), ordinaryFinal
      }))}`);
    await pair(); resetCoreBrowserEvidenceForTests();
    const opened = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'user_message', messageId: userId, time: Date.now(),
        text: 'Complete this native result only after its unique durable receipt.' }
    ] } });
    expect(opened.status).toBe(200);
    expect((await request('POST', '/correlations', { body: { conversationId,
      calls: [{ messageId: nativeCallId, requestId, tool: 'read', answered: false }]
    } })).body).toMatchObject({ complete: true, confirmed: [requestId] });
    await report(original);
    expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
    const first = await recordToolCall({ tool: 'read', args: { paths: ['/project/old.txt'] },
      content: [{ type: 'text', text: 'First durable result.' }],
      outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId });
    expect(first).toBeTruthy();

    // An exact session can legitimately accumulate >1024 other tool calls.
    // These are real durable appendEvent rows, not a mock of Bridge's reader:
    // the older matching result is outside its previous presentation tail.
    await Promise.all(Array.from({ length: 1030 }, (_, index) => appendEvent(opened.body.sessionId, {
      time: Date.now(), source: 'mcp', kind: 'tool_call',
      call: { ...first!, callId: randomUUID(),
        requestId: `wfr_unrelated_after_original_${index}` }
    })));
    const second = await recordToolCall({ tool: 'read', args: { paths: ['/project/replayed.txt'] },
      content: [{ type: 'text', text: 'Second transport result using the SAME native workflow.' }],
      outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId });
    expect(second?.callId).not.toBe(first!.callId);
    const all = await readEvents(opened.body.sessionId, { kinds: ['tool_call'] });
    expect(all.filter(item => item.kind === 'tool_call' &&
      item.call.requestId === requestId)).toHaveLength(2);
    expect((await report({ ...original, reason: 'associated', openCalls: 0, openRequestIds: [] })).status).toBe(200);
    await sessionControlsFor(opened.body.sessionId);
    // A single visible tail match cannot prove the complete unique per-message
    // terminal result. It must not release the native/Loop final or helper custody.
    expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
  }, 60_000);

