  it.each([
    { nativeTool: 'read', executedTool: 'exec_command', accepted: false },
    { nativeTool: 'exec_command', executedTool: 'read', accepted: false },
    { nativeTool: 'read', executedTool: 'read', accepted: true },
    { nativeTool: 'read', executedTool: 'exec_command', accepted: false, rowless: true },
    { nativeTool: 'read', executedTool: 'read', accepted: true, rowless: true },
    { nativeTool: 'read', executedTool: 'read', accepted: false, rowless: true, retag: true }
  ])('requires the ORIGINAL native Core tool type, not only a matching workflow request id, before durable native-final ACK ($nativeTool -> $executedTool)',
    async ({ nativeTool, executedTool, accepted, rowless, retag }) => {
      const conversationId = randomUUID(), originalQuestion = randomUUID();
      const requestId = 'wfr_wrong_tool_result_native_final_' + nativeTool + '_' + executedTool +
        (rowless ? '_early_rowless' : '');
      const nativeCallId = 'native-original-tool-execution-' + nativeTool;
      const ordinary = { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
        codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
        sourceUserMessageId: originalQuestion, coreCallMessageIds: [nativeCallId],
        allCoreRequestIds: [requestId], openRequestIds: [requestId] };
      const native = { documentId: 'one-native-tool-exact-type-hold',
        navigationEpoch: 5, shell: 'alternate', shellDiscovery: 'compatible',
        requestIds: [requestId] };
      const report = (ordinaryFinal: Record<string, unknown>) => request('GET',
        `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
          ...native, observedAt: Date.now(), ordinaryFinal
        }))}`);
      await pair(); resetCoreBrowserEvidenceForTests();
      const opened = await request('POST', '/events', { body: { conversationId, events: [{
        kind: 'user_message', messageId: originalQuestion, time: Date.now(),
        text: 'Keep this native invocation bound to its original requested tool.'
      }] } });
      expect(opened.status).toBe(200);
      if (rowless) {
        const early = await request('POST', '/correlations', { body: { conversationId,
          calls: [{ messageId: 'stream:rowless-workflow-first', requestId, answered: false }]
        } });
        expect(early.body).toMatchObject({ complete: true, confirmed: [requestId],
          sessionId: opened.body.sessionId });
      }
      expect((await request('POST', '/correlations', { body: { conversationId,
        calls: [{ messageId: nativeCallId, requestId, tool: nativeTool, answered: false }]
      } })).body).toMatchObject({ complete: true, confirmed: [requestId],
        sessionId: opened.body.sessionId });
      await report(ordinary);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(conversationId))?.reason).toBe('evidence');
      if (retag) {
        expect((await request('POST', '/correlations', { body: { conversationId,
          calls: [{ messageId: nativeCallId, requestId, tool: 'exec_command', answered: false }]
        } })).body.complete).toBe(true);
        expect(requestCorrelation(requestId)?.nativeCallAmbiguous).toBe(true);
      }
      const recorded = await recordToolCall({ tool: executedTool,
        args: { paths: ['/project/wrong-tool-result-must-not-ack.txt'] },
        content: [{ type: 'text', text: 'Original result, wrong tool identity.' }],
        outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId });
      expect(recorded).toMatchObject({ conversationId, attributionMethod: 'request_id' });
      await report({ ...ordinary, reason: 'associated', openCalls: 0, openRequestIds: [] });
      await sessionControlsFor(opened.body.sessionId);
      const wait = nativeFinalEvidenceWait(coreBrowserEvidence(conversationId));
      if (accepted) expect(wait).toBeNull();
      else expect(wait?.reason).toBe('evidence');
      const events = (await readEvents(opened.body.sessionId, { kinds: ['tool_call'], requireIntegrity: true }))
        .filter(event => event.kind === 'tool_call' && event.call.requestId === requestId);
      expect(events).toHaveLength(1);
      expect(events[0]).toMatchObject({ kind: 'tool_call', call: { tool: executedTool,
        requestId, conversationId, attributionMethod: 'request_id' } });
    }
  );

