  it('keeps the original Core receipt and destination unchanged while a damaged on-disk session is missing from the catalog, then joins once after safe repair', async () => {
    const conversationId = randomUUID(), requestId = 'wfr_incomplete_catalog_pretransfer';
    const messageId = 'native-catalog-valid-tool', receiptId = 'e8'.repeat(24);
    await pair();
    const opened = await request('POST', '/events', { body: { conversationId, events: [{
      kind: 'user_message', messageId: randomUUID(), time: Date.now(),
      text: 'Wait for complete session custody before moving the exact result.'
    }] } });
    expect(opened.status).toBe(200);
    const unowned = await recordToolCall({ tool: 'read',
      args: { paths: ['/project/one-original-execution.txt'] },
      content: [{ type: 'text', text: 'The original Core execution completed once.' }],
      outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId: null,
      resultReceiptId: receiptId });
    expect(unowned).toMatchObject({ conversationId: null, attributionMethod: 'unattributed',
      resultReceiptId: receiptId });
    let originalSourceId: string | null = null;
    for (const row of await sessionStoreModule.indexedSessions()) {
      if (row.conversationId !== null || row.title !== 'Unattributed activity') continue;
      if ((await readEvents(row.id, { kinds: ['tool_call'] })).some(event =>
        event.kind === 'tool_call' && event.call.callId === unowned!.callId))
        originalSourceId = row.id;
    }
    expect(originalSourceId).not.toBeNull();
    await flushSessions();
    const sourceFile = path.join(sessionStoreModule.sessionsRoot(), originalSourceId!, 'events.jsonl');
    const sourceBytes = await fs.readFile(sourceFile);
    const damagedDir = path.join(sessionStoreModule.sessionsRoot(), 'damaged-' + randomUUID());
    const correlation = { messageId, tool: 'read', requestId, answered: true, resultReceiptId: receiptId };
    // Never reuse/overwrite a prior fixture if another failed or was left on
    // disk for inspection. This is only the test-owned temporary session root.
    await fs.mkdir(damagedDir);
    await fs.writeFile(path.join(damagedDir, 'meta.json'), '{ damaged original metadata', 'utf8');
    // This fixture is isolated in bridge.test's temporary session root. Both
    // checkpoints missing must not silently mean this session never existed.
    resetSessionStoreForTests();
    try {
      const refused = await request('POST', '/correlations', { body: { conversationId,
        calls: [correlation] } });
      expect(refused.status).toBe(200);
      expect(refused.body.confirmedResultReceipts).toEqual([]);
      expect(await fs.readFile(sourceFile)).toEqual(sourceBytes);
      expect((await readEvents(opened.body.sessionId, { kinds: ['tool_call'], requireIntegrity: true }))
        .filter(event => event.kind === 'tool_call' && event.call.resultReceiptId === receiptId))
        .toHaveLength(0);
    } finally {
      await fs.rm(damagedDir, { recursive: true, force: true });
      resetSessionStoreForTests();
    }
    // No second execution: the same original durable result is still waiting
    // in Unattributed and can be moved once after the missing catalog source
    // is positively repaired and the exact native witness is repeated.
    const joined = await request('POST', '/correlations', { body: { conversationId,
      calls: [correlation] } });
    expect(joined.body.confirmedResultReceipts).toEqual([receiptId]);
    expect((await readEvents(opened.body.sessionId, { kinds: ['tool_call'], requireIntegrity: true }))
      .filter(event => event.kind === 'tool_call' && event.call.resultReceiptId === receiptId))
      .toHaveLength(1);
  });

