  it.each(['same-correlation-batch', 'after-correlation-ACK'])(
    'commits BOTH native Core message identities sharing one workflow request before acknowledging their browser correlation (%s)',
    async mode => {
      await pair();
      const conversationId = randomUUID();
      const requestId = `wfr_native_call_sibling_correlation_${mode}`;
      const opened = await request('POST', '/events', { body: { conversationId, events: [{
        kind: 'user_message', messageId: randomUUID(), time: Date.now(),
        text: 'Two real native tool-message parents, one workflow request id.'
      }] } });
      expect(opened.status).toBe(200);
      const original = { requestId, tool: 'read', messageId: 'native-correlation-original' };
      const sibling = { requestId, tool: 'read', messageId: 'native-correlation-sibling' };
      const first = await request('POST', '/correlations', { body: { conversationId,
        calls: mode === 'same-correlation-batch' ? [original, sibling] : [original]
      } });
      expect(first.body).toMatchObject({ complete: true, confirmed: [requestId],
        sessionId: opened.body.sessionId });
      if (mode === 'after-correlation-ACK') {
        const later = await request('POST', '/correlations', { body: { conversationId,
          calls: [sibling] } });
        expect(later.body).toMatchObject({ complete: true, confirmed: [requestId],
          sessionId: opened.body.sessionId });
      }
      // The ACK is for recording page ownership, not execution/finalization.
      // Both native messages must already be in the ONE committed workflow
      // ledger and its ambiguity veto must survive callback replay.
      expect(requestCorrelation(requestId)).toMatchObject({
        conversationId, sessionId: opened.body.sessionId,
        messageId: original.messageId,
        nativeCallAmbiguous: true
      });
      const duplicate = await request('POST', '/correlations', { body: { conversationId,
        calls: [original, sibling] } });
      expect(duplicate.body).toMatchObject({ complete: true, confirmed: [requestId] });
      expect(requestCorrelation(requestId)?.nativeCallAmbiguous).toBe(true);
      expect((await readEvents(opened.body.sessionId, { kinds: ['tool_call'] }))
        .filter(event => event.kind === 'tool_call')).toHaveLength(0);
    }
  );

  it('does not acknowledge sibling native-call evidence until its durable correlation barrier recovers from storage failure', async () => {
    await pair();
    const conversationId = randomUUID(), requestId = 'wfr_native_sibling_commit_failure';
    const opened = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'user_message', time: Date.now(), messageId: randomUUID(),
        text: 'Keep current native result custody until stored.' }
    ] } });
    expect(opened.status).toBe(200);
    expect((await request('POST', '/correlations', { body: { conversationId,
      calls: [{ requestId, tool: 'read', messageId: 'native-read-original' }]
    } })).body).toMatchObject({ confirmed: [requestId], complete: true });
    const durable = await import('../src/main/durable.js');
    const write = durable.writeDurableNow;
    let fail = true, successfulCommits = 0;
    const writer = vi.spyOn(durable, 'writeDurableNow').mockImplementation(async (name, value) => {
      if (name === 'request-correlations') {
        if (fail) {
          fail = false;
          throw Object.assign(new Error('simulated private disk path ENOSPC'), { code: 'ENOSPC' });
        }
        successfulCommits++;
      }
      return write(name, value);
    });
    const sibling = () => request('POST', '/correlations', { body: { conversationId,
      calls: [{ requestId, tool: 'read', messageId: 'native-read-sibling' }]
    } });
    try {
      const refused = await sibling();
      expect(refused.status).not.toBe(200);
      expect(refused.body?.complete).not.toBe(true);
      expect(requestCorrelation(requestId)).toMatchObject({
        sessionId: opened.body.sessionId, nativeCallAmbiguous: true
      });
      const recovered = await sibling();
      expect(recovered.body).toMatchObject({ confirmed: [requestId], complete: true });
      expect(successfulCommits).toBeGreaterThan(0);
    } finally { writer.mockRestore(); }
  });

