      await recordExactCall('discarded-page-exact-call-2');
      await settled();
      expect(continuationForSession(sessionId)?.token).toBe(token);
      expect(liveConversations().find(entry => entry.conversationId === conversationId)).toMatchObject({
        activeTurnId: null,
        generating: false
      });
