  it.each(['stop', 'completed-end', 'turn-start', 'user-message'] as const)(
  'retires the guarded ticket when a %s boundary queues during its durable open write', async boundary => {
    await pair();
    const suffix = { stop: '26', 'completed-end': '28', 'turn-start': '29', 'user-message': '30' }[boundary];
    const conversationId = `a1a1a1a1-0000-4000-8000-00000000ac${suffix}`;
    const gate = faultGate();
    let restoreWriter: () => void = () => undefined;
    try {
      await withThreshold(10_000, async () => {
        const opened = await request('POST', '/events', {
          body: { conversationId, events: over() }
        });
        const sessionId = opened.body.sessionId as string;
        const durable = await import('../src/main/durable.js');
        const writeDurableNow = durable.writeDurableNow;
        let restored = false;
        const writer = vi.spyOn(durable, 'writeDurableNow').mockImplementation(async (name, value) => {
          if (name !== CONTINUATIONS_STATE) return writeDurableNow(name, value);
          await gate.hold();
          writer.mockRestore();
          restored = true;
          return writeDurableNow(name, value);
        });
        restoreWriter = () => { if (!restored) writer.mockRestore(); };

        const requestId = `${boundary}-during-continuation-write`;
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'tool_evidence', time: Date.now(),
          calls: [{ messageId: `m-${requestId}`, tool: 'read', order: 0, answered: false, requestId }]
        }] } });
        const filing = recordToolCall({
          tool: 'read', args: { path: '/project/durable-race.ts' }, content: [{ type: 'text', text: 'exact result' }],
          outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId
        });
        await gate.entered;

        // The guarded open currently owns the observation serializer. Every boundary which would
        // reject the proof before publication must revoke that same ticket if it queued during the
        // durable write; final/Stop are not special cases.
        const at = Date.now() + 1;
        const boundaryEvent = boundary === 'stop'
          ? { kind: 'turn_end', time: at, turnId: requestId, outcome: 'stopped' }
          : boundary === 'completed-end'
            ? { kind: 'turn_end', time: at, turnId: requestId, outcome: 'completed' }
            : boundary === 'turn-start'
              ? { kind: 'turn_start', time: at, turnId: `${requestId}-next` }
              : { kind: 'user_message', time: at, messageId: `${requestId}-next`, text: 'Start the next task.' };
        const observed = request('POST', '/events', { body: { conversationId, events: [boundaryEvent] } });
        await new Promise(resolve => setTimeout(resolve, 10));
        gate.release();
        await Promise.all([filing, observed]);

        await vi.waitFor(() => expect(getLog().some(entry => entry.message.includes(
          `${conversationId} invalidated its attributed auto-compaction before source Send`
        ))).toBe(true), { timeout: 3000 });
        // A new page-live user/turn boundary may immediately earn a distinct ordinary automatic
        // ticket. The log above proves the attributed transaction itself was retired; terminal
        // boundaries have no new work and therefore leave no continuation at all.
        if (boundary === 'stop' || boundary === 'completed-end')
          expect(continuationForSession(sessionId)).toBeNull();
      });
    } finally {
      gate.release();
      restoreWriter();
    }
  });

