  it('serializes source claim behind a newly durable invalidation even when /status polls mid-abort', async () => {
    vi.useFakeTimers();
    await pair();
    const conversationId = 'a1a1a1a1-0000-4000-8000-00000000ac33';
    const gate = faultGate();
    let restoreWriter: () => void = () => undefined;
    try {
      await withThreshold(10_000, async () => {
        const opened = await request('POST', '/events', { body: { conversationId, events: over() } });
        const sessionId = opened.body.sessionId as string;
        const requestId = 'claim-versus-terminal-observation';
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'tool_evidence', time: Date.now(),
          calls: [{ messageId: `m-${requestId}`, tool: 'read', order: 0, answered: false, requestId }]
        }] } });
        await recordToolCall({
          tool: 'read', args: { path: '/project/claim-race.ts' }, content: [{ type: 'text', text: 'exact result' }],
          outcome: 'ok', durationMs: 1, startedAt: Date.now(), requestId
        });
        await vi.waitFor(() => expect(continuationForSession(sessionId)).toMatchObject({
          automatic: true,
          state: 'awaiting-summary',
          sourceSend: { state: 'not-attempted' }
        }), { timeout: 3000 });
        const token = continuationForSession(sessionId)!.token;

        await vi.advanceTimersByTimeAsync(2 * 60_000);
        await sweepStaleSwarm(Date.now());
        const initialStatus = await request('GET', '/status');
        const initialRepair = initialStatus.body.repairs?.find((repair: any) => repair.conversationId === conversationId);
        expect(initialRepair).toMatchObject({ conversationId, reason: 'compaction' });

        const durable = await import('../src/main/durable.js');
        let restored = false;
        const writer = vi.spyOn(durable, 'writeDurableNow').mockImplementationOnce(async (name, value) => {
          expect(name).toBe(CONTINUATIONS_STATE);
          await gate.hold();
          writer.mockRestore();
          restored = true;
          return durable.writeDurableNow(name, value);
        });
        restoreWriter = () => { if (!restored) writer.mockRestore(); };

        // Recording owns the conversation serializer and has already marked this proof invalid;
        // hold its durable abort while the extension performs its normal poll and source claim.
        const terminal = request('POST', '/events', { body: { conversationId, events: [{
          kind: 'turn_end', time: Date.now() + 1, turnId: 'claim-race-completed', outcome: 'completed'
        }] } });
        await gate.entered;
        const midAbortStatus = await request('GET', '/status');
        expect(midAbortStatus.status).toBe(200);
        expect(midAbortStatus.body.repairs ?? []).not.toEqual(expect.arrayContaining([
          expect.objectContaining({ conversationId })
        ]));
        expect((midAbortStatus.body.repairs ?? []).map((repair: any) => repair.token)).not.toContain(initialRepair.token);
        let attemptSettled = false;
        const attempt = request('POST', '/compact', {
          body: { conversationId, token, sourceAttempt: true }
        }).finally(() => { attemptSettled = true; });
        await vi.advanceTimersByTimeAsync(10);
        expect(attemptSettled).toBe(false);

        gate.release();
        const [terminalResponse, attemptResponse] = await Promise.all([terminal, attempt]);
        expect(terminalResponse.status).toBe(200);
        expect(attemptResponse.status).toBe(409);
        expect(continuationForSession(sessionId)).toBeNull();
        expect(getLog().some(entry => entry.message.includes(
          `${conversationId} invalidated its attributed auto-compaction before source Send`
        ))).toBe(true);
      });
    } finally {
      gate.release();
      restoreWriter();
      vi.useRealTimers();
    }
  });

