  /**
   * Missing browser pickups are not proof that an automatic context-protection obligation is
   * obsolete. The same durable ticket keeps asking every two minutes, across restart, until
   * the page positively reports a pre-Send failure or the user turns Auto off.
   */
  it.each([false, true])('keeps an unsent automatic ticket durable past five 2-minute pickups (restored: %s)', async restored => {
    vi.useFakeTimers();
    try {
      await pair();
      const conversationId = 'a1a1a1a1-0000-4000-8000-00000000ac06';
      await request('POST', '/events', {
        body: {
          conversationId,
          events: [{ kind: 'user_message', time: Date.now(), text: 'generate the huge handoff', messageId: 'm-auto-watch' }]
        }
      });
      const filed = await request('POST', '/compact', {
        body: { conversationId, ticket: true, automatic: true }
      });
      const token = filed.body.token as string;

      if (restored) {
        const { snapshotContinuations } = await import('../src/main/session/continuation.js');
        const snapshot = snapshotContinuations();
        resetBridgeForTests();
        await pair();
        await restoreContinuations({ ...snapshot, entries: snapshot.entries.map(entry => entry.token === token
          ? { ...entry, openedAt: Date.now() - 60_000 } : entry) });
      }

      const takeRepair = async (): Promise<{ conversationId: string; token: string; reason: string; focus: boolean } | null> => {
        await sweepStaleSwarm(Date.now());
        return (await request('GET', '/status')).body.repairs?.[0] ?? null;
      };
      await vi.advanceTimersByTimeAsync(2 * 60_000 - 1);
      expect(await takeRepair()).toBeNull();

      for (let attempt = 0; attempt < 5; attempt += 1) {
        await vi.advanceTimersByTimeAsync(attempt === 0 ? 1 : 2 * 60_000);
        const handout = await takeRepair();
        expect(handout).toMatchObject({ conversationId, reason: 'compaction', focus: true });
        await request('GET', `/status?repaired=${handout!.token}&repairAction=reloaded`);
        expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-summary' });
      }

      await vi.advanceTimersByTimeAsync(2 * 60_000);
      const sixth = await takeRepair();
      expect(sixth).toMatchObject({ conversationId, reason: 'compaction', focus: true });
      await request('GET', `/status?repaired=${sixth!.token}&repairAction=reloaded`);
      expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-summary', error: null });
      expect(continuationForSession(filed.body.sessionId as string)?.token).toBe(token);
    } finally {
      vi.useRealTimers();
    }
  });

  it.each(['unclaimed', 'prepared', 'restored', 'dispatched'] as const)(
    'bounds an unsent manual handoff even when no browser pickup completes (%s)', async shape => {
      vi.useFakeTimers();
      try {
        await pair();
        const conversationId = randomUUID();
        const recorded = await request('POST', '/events', { body: { conversationId, events: [
          { kind: 'user_message', time: Date.now(), messageId: randomUUID(), text: 'Continue the original production work.' }
        ] } });
        const sessionId = recorded.body.sessionId as string;
        const filed = await request('POST', '/compact', { body: { conversationId, ticket: true, automatic: false } });
        const token = filed.body.token as string;
        if (shape === 'prepared' || shape === 'dispatched') {
          expect((await request('POST', '/compact', { body: { conversationId, token, sourceAttempt: true } })).body.allowed).toBe(true);
        }
        if (shape === 'dispatched') {
          expect((await request('POST', '/compact', { body: { conversationId, token, sourceDispatch: true } })).body.armed).toBe(true);
        }
        // A browser that never claims or confirms its handout must not pause the budget.
        await vi.advanceTimersByTimeAsync(2 * 60_000);
        await sweepStaleSwarm(Date.now());
        await request('GET', '/status');
        await vi.advanceTimersByTimeAsync(8 * 60_000 - 1);
        await sweepStaleSwarm(Date.now());
        expect(continuationByToken(token)?.state).toBe('awaiting-summary');
        if (shape === 'restored') {
          const retained = snapshotContinuations();
          resetBridgeForTests();
          await pair();
          await restoreContinuations(retained);
        }
        await vi.advanceTimersByTimeAsync(2);
        await sweepStaleSwarm(Date.now());
        expect(continuationByToken(token)).toMatchObject(shape === 'dispatched'
          ? { state: 'awaiting-summary', sourceSend: { state: 'dispatched-unresolved', messageId: null } }
          : { state: 'aborted', error: 'handoff_never_sent', sourceSend: { messageId: null } });
        // A deadline retires only an unsubmitted request. It fabricates no brief, final,
        // native ACK, replacement chat or successful original-task result.
        expect(continuationByToken(token)?.handoffId).toBeNull();
        expect((await getSession(sessionId))?.conversationId).toBe(conversationId);
        expect(pendingCommands().filter(command => command.what === `resume:${sessionId}`)).toHaveLength(0);
        if (shape !== 'dispatched') {
          expect((await request('POST', '/compact', { body: { conversationId, token, sourceDispatch: true } })).status).toBe(409);
          expect((await request('GET', '/status')).body.repairs ?? []).toEqual([]);
        }
      } finally {
        vi.useRealTimers();
      }
    }
  );

