  it('does not let repeated empty provider failures or a foreign document postpone the exact automatic fallback', async () => {
    const previous = getConfig();
    vi.useFakeTimers();
    try {
      await saveConfig({
        ...previous,
        sessions: { ...previous.sessions, advisoryTokens: 10_000, limitTokens: 10_000 },
        compaction: { auto: true, autoTokens: 10_000 }
      });
      await pair();
      const conversationId = 'a1a1a1a1-0000-4000-8000-00000000ac41';
      const foreignConversation = 'b1b1b1b1-0000-4000-8000-00000000ac41';
      const opened = await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'user_message', time: Date.now(), text: 'x'.repeat(44_000), messageId: 'm-empty-recovery-loop' }
      ] } });
      const filed = await request('POST', '/compact', {
        body: { conversationId, ticket: true, automatic: true }
      });
      const token = filed.body.token as string;
      expect(continuationByToken(token)).toMatchObject({
        sessionId: opened.body.sessionId,
        from: conversationId,
        state: 'awaiting-summary',
        sourceSend: { state: 'not-attempted' },
        destinationSend: { state: 'not-attempted', conversationId: null }
      });

      // Each replacement document reaches a terminal network error without producing a model
      // message or Core work. A different chat does produce text; neither fact is progress for
      // this exact ticket.
      for (let attempt = 1; attempt <= 5; attempt += 1) {
        await vi.advanceTimersByTimeAsync(60_000);
        const turnId = `empty-recovery-document-${attempt}`;
        await request('POST', '/events', { body: { conversationId, events: [
          { kind: 'turn_start', time: Date.now(), turnId },
          { kind: 'page_tool', time: Date.now(), turnId, messageId: `browser-repair:${attempt}`,
            text: 'Reloaded chat to recover an unrecognizable open turn.' },
          { kind: 'chat_error', time: Date.now(), turnId,
            text: 'A network error occurred. Please check your connection and try again.',
            recoverable: true, blocking: true },
          { kind: 'turn_end', time: Date.now(), turnId, outcome: 'failed' }
        ] } });
        await recordToolCall({
          tool: 'session_finish', args: {}, content: [{ type: 'text', text: 'failed recovery turn closed' }],
          outcome: 'ok', durationMs: 1, startedAt: Date.now(), endsActivity: true,
          conversationId, sessionId: opened.body.sessionId as string
        });
        expect(await recordProgress(opened.body.sessionId as string, `browser-repair:${attempt}`,
          'Reloaded chat to recover an unrecognizable open turn.')).not.toBeNull();
        await request('GET', `/activity?conversationId=${conversationId}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
          documentId: `stale-recovery-document-${attempt}`,
          navigationEpoch: attempt,
          observedAt: Date.now(),
          shell: 'classic',
          shellDiscovery: 'compatible',
          requestIds: [],
          turnId
        }))}`);
        await request('POST', '/events', { body: { conversationId: foreignConversation, events: [{
          kind: 'assistant_message', time: Date.now(), turnId: `foreign-${attempt}`,
          messageId: `foreign-message-${attempt}`, text: 'Useful work in another browser document.',
          state: 'streaming', activeNow: true
        }] } });
      }
      await vi.advanceTimersByTimeAsync(1);
      await sweepStaleSwarm(Date.now());

      expect(continuationByToken(token)).toMatchObject({
        sessionId: opened.body.sessionId,
        from: conversationId,
        state: 'awaiting-chat',
        sourceSend: { state: 'not-attempted' },
        destinationSend: { state: 'not-attempted', conversationId: null }
      });
      expect(pendingCommands().filter(command => command.what === `resume:${opened.body.sessionId}`)).toHaveLength(1);

      // The token CAS and existing-command guard make repeated sweeps idempotent: the fallback
      // cannot replay either source Send or destination bootstrap.
      await sweepStaleSwarm(Date.now());
      expect(pendingCommands().filter(command => command.what === `resume:${opened.body.sessionId}`)).toHaveLength(1);
    } finally {
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

  it.each(['provider', 'core', 'native'] as const)('lets real %s progress extend the exact automatic fallback clock', async progress => {
    const previous = getConfig();
    const isolatedSessionRoot = path.join(dir, `compaction-progress-${progress}`);
    const began = performance.now();
    const stages: Record<string, number> = {};
    const mark = (stage: string) => { stages[stage] = Math.round(performance.now() - began); };
    onTestFinished(() => {
      if (performance.now() - began >= 15_000) console.info('compaction progress fixture stages', progress, stages);
    });
    // Each deadline is evaluated by the explicit sweep below. Advance only its
    // observed wall clock; replaying every background timer also drives unrelated
    // persistence and maintenance while the large real recorder burst is written.
    vi.useFakeTimers({ toFake: ['Date'] });
    try {
      // Earlier cases retain their own recordings for cold-restore checks. They are
      // unrelated to this ticket's 600-row cursor scenario; give it an isolated
      // catalog using the same store-owner seam as mixed-loop-cold-restore below.
      mark('before-catalog-flush');
      await flushSessions();
      resetSessionStoreForTests();
      resetRecorderForTests();
      initSessionStore(isolatedSessionRoot);
      mark('catalog-isolated');
      await saveConfig({
        ...previous,
        sessions: { ...previous.sessions, advisoryTokens: 10_000, limitTokens: 10_000 },
        compaction: { auto: true, autoTokens: 10_000 }
      });
      await pair();
      const conversationId = progress === 'provider'
        ? 'a1a1a1a1-0000-4000-8000-00000000ac42'
        : progress === 'core'
          ? 'a1a1a1a1-0000-4000-8000-00000000ac43'
          : 'a1a1a1a1-0000-4000-8000-00000000ac45';
      const opened = await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'user_message', time: Date.now(), text: 'x'.repeat(44_000), messageId: `m-${progress}-clock` }
      ] } });
      const sessionId = opened.body.sessionId as string;
      const filed = await request('POST', '/compact', {
        body: { conversationId, ticket: true, automatic: true }
      });
      const token = filed.body.token as string;
      // Seed the ticket's one-time linear cursor before the later burst. The follow-up sweep must
      // find genuine work through the bounded incremental path, not by rescanning full history.
      await sweepStaleSwarm(Date.now());
      mark('ticket-cursor-seeded');

      vi.setSystemTime(Date.now() + 4 * 60_000);
      if (progress === 'provider') {
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'assistant_message', time: Date.now(), turnId: 'real-provider-progress',
          messageId: 'real-provider-progress', text: 'The provider is now writing the recovery answer.',
          state: 'streaming', activeNow: true
        }] } });
        // The quiet-window reader, not 600 separate disk appends, is under test.
        // Obtain the real recorder's row shape through HTTP, then seed the owned
        // journal backlog in one write and reopen it through normal crash recovery.
        // All 600 distinct, out-of-order rows remain behind the exact provider row.
        const noise = await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'page_tool', time: Date.now() - 10 * 60_000, turnId: 'reload-noise-seed',
          messageId: 'browser-repair:noise-seed',
          text: 'Reloaded chat to recover an unrecognizable open turn.'
        }] } });
        expect(noise.status).toBe(200);
        await flushSessions();
        const sourceEvents = await readEvents(sessionId);
        const template = sourceEvents.find(event => event.kind === 'page_tool' &&
          event.messageId === 'browser-repair:noise-seed')!;
        expect(template).toMatchObject({ kind: 'page_tool', source: 'extension' });
        const lastSeq = Math.max(...sourceEvents.map(event => event.seq));
        const backlog = Array.from({ length: 599 }, (_, index) => ({
          ...template, seq: lastSeq + index + 1, turnId: `reload-noise-${index}`,
          messageId: `browser-repair:noise-${index}`
        }));
        const store = await import('../src/main/session/store.js');
        await fs.appendFile(path.join(store.sessionsRoot(), sessionId, 'events.jsonl'),
          backlog.map(event => JSON.stringify(event) + '\n').join(''), 'utf8');
        resetSessionStoreForTests();
        expect((await readEvents(sessionId)).filter(event => event.kind === 'page_tool' &&
          event.messageId?.startsWith('browser-repair:noise-'))).toHaveLength(600);
        expect((await getSession(sessionId))!.events).toBeGreaterThan(600);
        mark('600-durable-noise-rows-reopened');
      } else if (progress === 'core') {
        await recordToolCall({
          tool: 'read', args: { path: '/project/recovery-state.ts' },
          content: [{ type: 'text', text: 'exact Core work completed' }], outcome: 'ok', durationMs: 1,
          startedAt: Date.now(), requestId: 'exact-compaction-core-progress', conversationId, sessionId
        });
      } else {
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'page_tool', time: Date.now(), turnId: 'real-native-tool-progress',
          messageId: 'real-native-tool-progress',
          text: 'Retrying recovery analysis after reload wake.'
        }] } });
      }

      mark('exact-progress-recorded');
      vi.setSystemTime(Date.now() + 60_001);
      await sweepStaleSwarm(Date.now());
      expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-summary', from: conversationId });
      mark('extended-deadline-checked');

      // Native page-tool rows use their first exact observation as the conservative activity
      // clock; provider/Core rows retain their stronger recorded completion timestamps.
      vi.setSystemTime(Date.now() + 5 * 60_000);
      await sweepStaleSwarm(Date.now());
      expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-chat', from: conversationId });
      expect(pendingCommands().filter(command => command.what === `resume:${sessionId}`)).toHaveLength(1);
      mark('one-original-resume-checked');
    } finally {
      vi.useRealTimers();
      await flushSessions();
      resetRecorderForTests();
      resetSessionStoreForTests();
      initSessionStore(sessionCaseRoot);
      await saveConfig(previous);
      mark('catalog-restored');
    }
  });

  it.each(['revision-only', 'presentation-tail-burst', 'final-transition'] as const)(
    'tracks growing canonical assistant text through the %s cursor case',
    async cursorCase => {
      const previous = getConfig();
      vi.useFakeTimers();
      try {
        await saveConfig({
          ...previous,
          sessions: { ...previous.sessions, advisoryTokens: 10_000, limitTokens: 10_000 },
          compaction: { auto: true, autoTokens: 10_000 }
        });
        await pair();
        const conversationId = cursorCase === 'revision-only'
          ? 'a1a1a1a1-0000-4000-8000-00000000ac46'
          : cursorCase === 'presentation-tail-burst'
            ? 'a1a1a1a1-0000-4000-8000-00000000ac47'
            : 'a1a1a1a1-0000-4000-8000-00000000ac50';
        const messageId = `growing-compaction-summary-${cursorCase}`;
        const opened = await request('POST', '/events', { body: { conversationId, events: [
          { kind: 'user_message', time: Date.now(), text: 'x'.repeat(44_000), messageId: `m-${cursorCase}` }
        ] } });
        const sessionId = opened.body.sessionId as string;
        const filed = await request('POST', '/compact', {
          body: { conversationId, ticket: true, automatic: true }
        });
        const token = filed.body.token as string;
        await sweepStaleSwarm(Date.now());

        await vi.advanceTimersByTimeAsync(4 * 60_000);
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'assistant_message', time: Date.now(), turnId: `turn-${cursorCase}`,
          messageId, text: 'Writing the exact handoff', state: 'streaming', activeNow: true
        }] } });
        if (cursorCase === 'presentation-tail-burst') {
          // A revised canonical message retains this earlier origin. More than the old minimum
          // presentation-tail page follows it, so a later revision cannot be found by slicing on
          // origin and then advancing a logical-event counter.
          await request('POST', '/events', { body: { conversationId, events: Array.from({ length: 100 }, (_, index) => ({
            kind: 'page_tool', time: Date.now(), turnId: `repair-backlog-${index}`,
            messageId: `browser-repair:backlog-${index}`,
            text: 'Reloaded chat to recover an unrecognizable open turn.'
          })) } });
        }
        await sweepStaleSwarm(Date.now());
        const original = (await readEvents(sessionId)).find(event =>
          event.kind === 'assistant_message' && event.messageId === messageId)!;
        const logicalEvents = (await getSession(sessionId))!.events;

        await vi.advanceTimersByTimeAsync(4 * 60_000);
        await request('POST', '/events', { body: { conversationId, events: [{
          kind: 'assistant_message', time: Date.now(), turnId: `turn-${cursorCase}`,
          messageId, text: cursorCase === 'final-transition'
            ? 'Writing the exact handoff'
            : 'Writing the exact handoff with newly streamed provider detail.',
          state: cursorCase === 'final-transition' ? 'final' : 'streaming',
          activeNow: cursorCase !== 'final-transition'
        }] } });
        const revised = (await readEvents(sessionId)).find(event =>
          event.kind === 'assistant_message' && event.messageId === messageId)!;
        expect(revised.seq).toBeGreaterThan(original.seq);
        expect((await getSession(sessionId))!.events).toBe(logicalEvents);
        if (cursorCase === 'presentation-tail-burst') {
          // One new logical row makes the old events-count shortcut enter its recent-tail branch;
          // the exact sequence cursor must still see the old-origin assistant revision before it.
          await request('POST', '/events', { body: { conversationId, events: [{
            kind: 'page_tool', time: Date.now(), turnId: 'repair-after-revision',
            messageId: 'browser-repair:after-revision',
            text: 'Reloaded chat to recover an unrecognizable open turn.'
          }] } });
        }

        await vi.advanceTimersByTimeAsync(60_001);
        await sweepStaleSwarm(Date.now());
        expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-summary', from: conversationId });

        // The semantic revision committed between bridge observations. Its exact discovery sweep
        // is the conservative clock boundary, so allow a full five quiet minutes after it.
        await vi.advanceTimersByTimeAsync(5 * 60_000);
        await sweepStaleSwarm(Date.now());
        expect(continuationByToken(token)).toMatchObject({ state: 'awaiting-chat', from: conversationId });
        expect(pendingCommands().filter(command => command.what === `resume:${sessionId}`)).toHaveLength(1);
      } finally {
        await saveConfig(previous);
        vi.useRealTimers();
      }
    }
  );

