  it('does not retire a newer in-place command while exact Cancel retirement awaits persistence', async ({ onTestFinished }) => {
    const from = 'c-cancel-command-replaced';
    const source = await createSession({ title: 'Cancel retirement race', conversationId: from });
    const a = await readyContinuation(source.id, 'Retire only this handoff', from);
    const commandA = queueResume(source.id, a)!;
    await flushDurable();
    const durable = await import('../src/main/durable.js');
    const original = durable.writeDurableNow;
    const gate = faultGate();
    let held = false;
    let retirementSnapshot: unknown;
    const writer = vi.spyOn(durable, 'writeDurableNow').mockImplementation(async (name, value) => {
      if (!held && name === 'bridge-commands' && !(value as any).commands.some((row: any) => row.id === commandA.id)) {
        held = true; retirementSnapshot = structuredClone(value); await gate.hold();
      }
      return original(name, value);
    });
    const release = () => { gate.release(); writer.mockRestore(); };
    onTestFinished(release);
    const cancelling = (cancelResumeNow as (...args: any[]) => Promise<boolean>)(source.id, 'cancelled', a);
    try {
      await gate.entered;
      expect(continuationByToken(a)?.state).toBe('aborted');
      const continuation = await import('../src/main/session/continuation.js');
      const openedB = await openContinuationNow(source.id, from, false);
      expect((await continuation.beginContinuationSourceSendNow(openedB.token))?.allowed).toBe(true);
      expect(await continuation.dispatchContinuationSourceSendNow(openedB.token)).toBe(true);
      expect(await continuation.bindContinuationSourceMessageNow(openedB.token, 'manual-b-native-sent')).toBe(true);
      expect(await attachSummary(openedB.token, `New exact command survives old retirement\n\n${SAMPLE_BRIEF}`)).not.toBeNull();
      const b = openedB.token;
      const commandB = queueResume(source.id, b)!;
      expect(commandB.id).toBe(commandA.id);
      const before = continuationByToken(b);
      gate.release();
      expect(await cancelling).toBe(true);
      expect(continuationByToken(b)).toEqual(before);
      expect(pendingCommands()).toEqual([expect.objectContaining({ id: commandB.id })]);
      await flushDurable();
      expect((await readDurable<any>('bridge-commands')).commands).toEqual([
        expect.objectContaining({ id: commandB.id, spec: { type: 'resume', sessionId: source.id, token: b } })
      ]);
      // A crash immediately after the old removal fsync loses every later debounced rewrite.
      // Restore that exact disk boundary, not the eventually-flushed in-memory B generation.
      const wal = await readDurable<ContinuationSnapshot>(CONTINUATIONS_STATE);
      await durable.writeDurableNow('bridge-commands', retirementSnapshot);
      resetBridgeForTests();
      await restoreContinuations(wal);
      await restoreCommands();
      expect(continuationByToken(b)).toEqual(before);
      expect(pendingCommands()).toEqual([expect.objectContaining({ what: `resume:${source.id}` })]);
      await flushDurable();
      expect((await readDurable<any>('bridge-commands')).commands).toEqual([
        expect.objectContaining({ spec: { type: 'resume', sessionId: source.id, token: b } })
      ]);
    } finally { release(); await cancelling; }
  });

