  /** A bootstrap that never reached a tab has no chat to name. */
  it('does not name anything for a failed acknowledgement', async ({ signal, onTestFailed }) => {
    let phase = 'pair', phaseStarted = performance.now(), sourceSessionId: string | null = null;
    const markPhase = (next: string): void => {
      signal.throwIfAborted();
      phase = next;
      phaseStarted = performance.now();
    };
    const step = async <T>(next: string, work: () => Promise<T>): Promise<T> => {
      markPhase(next);
      const result = await work();
      // A timed-out HTTP/storage await must not resume later and write into the next case.
      signal.throwIfAborted();
      return result;
    };
    onTestFailed(() => {
      const entries = snapshotContinuations().entries;
      console.error('[bridge:failed-acknowledgement-stage]', JSON.stringify({
        phase, elapsedMs: Math.round(performance.now() - phaseStarted),
        resumeOpening: resumeOpeningChat(), continuationCount: entries.length,
        continuations: entries.slice(0, 16).map(entry => ({
          state: entry.state, source: entry.sessionId === sourceSessionId, claimed: entry.claimedBy !== null
        }))
      }));
    });
    await step('pair', pair);
    const source = await step('create-session', () => createSession({ title: 'Never opened' }));
    sourceSessionId = source.id;
    const continuationToken = await step('prepare-continuation', () =>
      readyContinuation(source.id, 'carry on', 'c-compacted', null, markPhase));
    markPhase('queue-resume');
    const command = queueResume(source.id, continuationToken)!;
    await step('redeem', () => redeem(command.id));
    const conversationId = 'dddddddd-eeee-ffff-0000-111111111111';
    await step('failed-ack', () => request('POST', '/commands/ack', {
      body: { id: command.id, status: 'failed', error: 'tab died', conversationId }
    }));
    // The safe pre-Send failure now retains the original handoff. End that retry explicitly
    // before presenting the same untrusted URL as a user-started chat; this test is about
    // attribution, not the replacement-chat collision fence.
    expect(await step('cancel-resume', () => cancelResumeNow(source.id))).toBe(true);
    markPhase('post-cancel-recorder-gate');
    expect(resumeOpeningChat(), 'the cancelled sole continuation must release the recorder gate').toBe(false);

    const reply = await step('record-user-events', () => request('POST', '/events', {
      body: {
        conversationId,
        events: [{ kind: 'user_message', time: Date.now(), text: 'a chat the user started', messageId: 'm-own' }]
      }
    }));
    const summary = await step('read-recorded-session', () => getSession(reply.body.sessionId));
    markPhase('assert-attribution');
    expect(summary?.title).toBe('a chat the user started');
    expect(summary?.origin).toBeNull();
  });

  it.for(['live', 'cancelled'] as const)(
    'rechecks %s continuation custody before opening after a durable lease', async (custody, { signal, onTestFinished }) => {
      await pair();
      signal.throwIfAborted();
      const source = await createSession({ title: 'Opening lease cancellation race' });
      signal.throwIfAborted();
      const token = await readyContinuation(source.id, 'retain exact opening custody', 'c-compacted', null,
        () => signal.throwIfAborted());
      signal.throwIfAborted();
      const durable = await import('../src/main/durable.js');
      signal.throwIfAborted();
      const realWrite = durable.writeDurableNow;
      const leaseGate = faultGate(), retirementGate = faultGate();
      let commandId: string | null = null, heldLease = false, heldRetirement = false;
      let cancelling: Promise<boolean> | null = null;
      let leasePublished!: () => void;
      const afterLeasePublication = new Promise<void>(resolve => { leasePublished = resolve; });
      const writer = vi.spyOn(durable, 'writeDurableNow').mockImplementation(async (name, value) => {
        const rows = name === 'bridge-commands' ? (value as any)?.commands as any[] | undefined : undefined;
        if (!heldLease && rows?.some(row => row.spec.type === 'resume' && row.spec.token === token &&
            row.phase === 'leased' && row.owner === null)) {
          heldLease = true;
          await leaseGate.hold();
          await realWrite(name, value);
          // The real durable write has returned. This event-loop boundary lets its caller's
          // publication/opening microtasks finish; no guessed delay or deadline advance.
          setImmediate(leasePublished);
          return;
        }
        if (custody === 'cancelled' && !heldRetirement && commandId !== null && rows &&
            !rows.some(row => row.id === commandId)) {
          heldRetirement = true;
          await retirementGate.hold();
        }
        return realWrite(name, value);
      });
      const release = (): void => {
        leaseGate.release();
        retirementGate.release();
        writer.mockRestore();
      };
      onTestFinished(release);
      try {
        commandId = queueResume(source.id, token)!.id;
        await leaseGate.entered;
        signal.throwIfAborted();
        expect(resumeOpeningChat()).toBe(false);
        expect(opened).toEqual([]);
        if (custody === 'cancelled') {
          cancelling = cancelResumeNow(source.id);
          await retirementGate.entered;
          signal.throwIfAborted();
          // Abort has committed, but cancellation still owns its unfinished command removal.
          expect(continuationByToken(token)?.state).toBe('aborted');
          expect(pendingCommands().some(command => command.id === commandId)).toBe(true);
          expect(resumeOpeningChat()).toBe(false);
        }
        leaseGate.release();
        await afterLeasePublication;
        signal.throwIfAborted();
        expect(opened).toEqual(custody === 'live' ? [commandUrl(commandId)] : []);
        expect(resumeOpeningChat()).toBe(custody === 'live');
        if (custody === 'live') {
          await redeem(commandId, 'live-opening-lease-page');
          signal.throwIfAborted();
          expect(snapshotContinuations().entries.find(entry => entry.token === token)).toMatchObject({
            state: 'claimed', claimedBy: commandId, destinationSend: { state: 'not-attempted' }
          });
          expect(await cancelResumeNow(source.id)).toBe(true);
        } else {
          retirementGate.release();
          expect(await cancelling).toBe(true);
        }
        expect(pendingCommands()).toEqual([]);
        expect(resumeOpeningChat()).toBe(false);
      } finally {
        release();
        if (cancelling) await cancelling;
      }
    });

