    const readiness = { createdAt: before.createdAt, tab: 42, documentId: 'worker-document', navigationEpoch: 3,
      client: 'worker-recorder', waitingSince: Date.now(), observedAt: Date.now(), blockedBy: ['composer-draft'] };
    const report = async (value: unknown, owner = browser, chat = conversationId, commandId = id) => {
      await request('POST', '/commands/revivals/pending', { browser: owner,
        body: { entries: [{ id: commandId, conversationId: chat, readiness: value }] } });
      await flushDurable();
      return (await readDurable<any>('bridge-commands')).commands.find((row: any) => row.id === id)?.revivalReadiness;
    };
