  it('retains real recorded tool image output before treating a prose-free completed worker as a closable result', async () => {
    await pair();
    spawn({ workers: [{ task: 'produce an image artifact, with no assistant prose' }],
      caller: { conversationId: PRIME_CHAT } });
    const command = await redeem();
    const conversationId = 'decafbad-7654-3210-fedc-ba9876543294';
    expect((await request('POST', '/commands/ack', { body: {
      id: command.id, status: 'sent', conversationId, agent: 'worker-1'
    } })).status).toBe(200);
    const now = Date.now();
    const turnId = 'worker-native-asset-only';
    const started = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'turn_start', time: now, turnId },
      { kind: 'page_tool', time: now + 1, turnId, messageId: 'worker-image-output',
        text: 'Produced the requested image artifact' },
      { kind: 'tool_evidence', time: now + 2, turnId, calls: [{
        messageId: 'worker-image-call', tool: 'screenshot', order: 0, answered: true,
        requestId: 'wfr_worker_native_asset'
      }] }
    ] } });
    expect(started.status).toBe(200);
    // The screenshot's bytes, not the page-tool label, establish artifact custody.
    const png = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9fSqV4oAAAAASUVORK5CYII=';
    const recorded = await recordToolCall({
      tool: 'screenshot', args: {}, content: [{ type: 'image', data: png, mimeType: 'image/png' }],
      outcome: 'ok', durationMs: 1, startedAt: now + 2,
      requestId: 'wfr_worker_native_asset', conversationId
    });
    expect(recorded?.assets).toEqual([expect.objectContaining({
      id: expect.any(String), mimeType: 'image/png', bytes: expect.any(Number)
    })]);
    const assetId = recorded!.assets![0]!.id;
    const sessionId = started.body.sessionId as string;
    const storedTool = (await readEvents(sessionId)).find(row =>
      row.kind === 'tool_call' && row.call.requestId === 'wfr_worker_native_asset');
    expect(storedTool?.kind === 'tool_call' ? storedTool.call.assets?.[0]?.id : null).toBe(assetId);

    expect((await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'assistant_message', time: now + 3, turnId,
        messageId: 'worker-image-no-prose', text: '', state: 'final', final: true },
      { kind: 'turn_end', time: now + 4, turnId, outcome: 'completed' }
    ] } })).status).toBe(200);
    // Missing prose alone does not invalidate an actual artifact. Nor can the
    // page close while Prime only has recorder evidence but no durable result custody.
    expect(swarmStateForCaller({ conversationId: PRIME_CHAT }).agents.find(row => row.id === 'worker-1')?.state)
      .toBe('active');
    const before = (await request('POST', '/status', { body: { openConversations: [conversationId] } })).body;
    expect(before.workerTabCloseClaims?.[conversationId]).toBeUndefined();

    // The orphan sweep can free an idle slot, but cannot substitute a generic
    // 'completed' sentence for the actual image output or authorize losing it.
    await sweepStaleSwarm(now + STALE_SWARM_MS + 10_000);
    const prime = swarmStateForCaller({ conversationId: PRIME_CHAT });
    const retained = prime.agents.find(row => row.id === 'worker-1')!;
    const primeQueue = (await readDurable<any>('swarm'))?.agents.find((row: any) => row.info?.id === PRIME_ID)?.queue ?? [];
    const offeredAsset = primeQueue.some((row: any) => row.text.includes(assetId));
    // A Prime may have ACKed only a generic status, not the native asset. Even
    // after that ACK critically persists it cannot grant a destructive close.
    if (!offeredAsset) {
      offerMessages(PRIME_ID);
      acknowledgeOffers(PRIME_ID, false, Date.now() + 1);
      expect(await persistCriticalSwarmNow()).toBe(true);
    }
    const status = (await request('POST', '/status', { body: { openConversations: [conversationId] } })).body;
    if (!offeredAsset) {
      expect(status.workerTabCloseClaims?.[conversationId]).toBeUndefined();
      // A synthesized quiescence notice may release a slot, but is not the
      // actual model's artifact-only answer retained as info.result.
      expect(retained.result).toBeNull();
    }
    expect((await readEvents(sessionId)).some(row =>
      row.kind === 'tool_call' && row.call.assets?.some(asset => asset.id === assetId))).toBe(true);
  });

