  it.each(['before-offer', 'after-offer'])(
    'holds an ACKed worker result open while its exact MCP tool remains running $s', async order => {
    const previous = getConfig();
    await saveConfig({ ...previous, ui: { ...previous.ui, tabsToKeepOpen: 1 },
      multiAgent: { ...previous.multiAgent, maxWorkers: 2 } });
    let releaseTool: (() => void) | undefined;
    let heldTool: Promise<void> | undefined;
    try {
      await pair();
      spawn({ workers: [{ task: 'retain the finished result while Core work is live' },
        { task: 'work independently' }], caller: { conversationId: PRIME_CHAT } });
      const command = await redeem();
      const conversationId = order === 'before-offer'
        ? 'decafbad-7654-3210-fedc-ba9876543261'
        : 'decafbad-7654-3210-fedc-ba9876543260';
      const sibling = 'decafbad-7654-3210-fedc-ba9876543259';
      expect(bindConversation('worker-2', sibling)).toBe(true);
      expect((await request('POST', '/commands/ack', { body: {
        id: command.id, status: 'sent', conversationId, agent: 'worker-1'
      } })).status).toBe(200);
      const now = Date.now();
      const raw = 'RESULT: committed but ongoing exact Core work must still block close.\n';
      expect((await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'turn_start', time: now, turnId: 'native-running-tool-close-veto' },
        { kind: 'assistant_message', time: now + 1, turnId: 'native-running-tool-close-veto',
          messageId: 'native-running-tool-final', text: raw, final: true, state: 'final' },
        { kind: 'turn_end', time: now + 2, turnId: 'native-running-tool-close-veto', outcome: 'completed' }
      ] } })).status).toBe(200);
      const worker = (await readDurable<any>('swarm')).agents.find((row: any) =>
        row.info.id === 'worker-1');
      expect(worker?.info).toMatchObject({ state: 'sleeping', result: raw,
        stopReportId: expect.any(String) });
      expect(offerMessages(PRIME_ID).map(row => row.id)).toEqual([worker.info.stopReportId]);
      expect(acknowledgeOffers(PRIME_ID, false, Date.now() + 1).map(row => row.id))
        .toEqual([worker.info.stopReportId]);
      expect(await persistCriticalSwarmNow()).toBe(true);
      let oldClaim: string | undefined;
      if (order === 'after-offer') {
        oldClaim = (await request('POST', '/status', { body: {
          openConversations: [conversationId, sibling]
        } })).body.workerTabCloseClaims?.[conversationId];
        expect(oldClaim).toMatch(/^[a-f0-9]{32}$/);
      }
      const calls = await import('../src/main/mcp/call-context.js');
      const session = await findSessionByConversation(conversationId, { requireUnique: true });
      expect(session?.id).toEqual(expect.any(String));
      heldTool = calls.trackInFlight({
        startedAt: Date.now(), transportKey: null, agent: 'worker-1',
        caller: { transportKey: null, requestId: 'wfr_exact_running_close_veto',
          conversationId, sessionId: session!.id },
        outcome: null, evidence: calls.emptyEvidence()
      }, () => new Promise<void>(resolve => { releaseTool = resolve; }));
      await Promise.resolve();
      expect(calls.runningToolCalls(conversationId)).toBe(1);
      const held = (await request('POST', '/status', { body: {
        openConversations: [conversationId, sibling]
      } })).body;
      if (order === 'before-offer') {
        expect(held.workerTabCloseClaims?.[conversationId]).toBeUndefined();
      } else {
        expect((await request('POST', '/browser/worker-tab-close', { body: {
          action: 'claim', conversationId, claimId: oldClaim
        } })).status).toBe(409);
      }
      expect(held.workerTabCloseClaims?.[sibling]).toBeUndefined();
      releaseTool?.();
      await heldTool;
      heldTool = undefined;
      releaseTool = undefined;
      expect(calls.runningToolCalls(conversationId)).toBe(0);
      const eligible = (await request('POST', '/status', { body: {
        openConversations: [conversationId, sibling]
      } })).body;
      const claim = eligible.workerTabCloseClaims?.[conversationId];
      expect(claim).toMatch(/^[a-f0-9]{32}$/);
      if (oldClaim) expect(claim).not.toBe(oldClaim);
      expect(eligible.workerTabCloseClaims?.[sibling]).toBeUndefined();
      expect((await request('POST', '/browser/worker-tab-close', { body: {
        action: 'claim', conversationId, claimId: claim
      } })).status).toBe(200);
      expect((await readDurable<any>('swarm')).agents.find((row: any) =>
        row.info.id === 'worker-1')?.info).toMatchObject({ result: raw,
        stopReportId: worker.info.stopReportId, stopReportAcknowledgedAt: expect.any(Number) });
    } finally {
      releaseTool?.();
      await heldTool;
      await saveConfig(previous);
    }
  });

