  /** A full browser queue is transport pressure, not proof that an invited worker failed. */
  it('spills an untouched worker to its durable broker invitation when a resume fills the queue', async () => {
    const previous = getConfig();
    try {
      await pair();
      await saveConfig({ ...previous, ui: { ...previous.ui, automationPaused: true } });
      applyAutomationPause(true);
      spawn({ workers: [{ task: 'the worker that gets pushed out of the queue' }], caller: { conversationId: PRIME_CHAT } });
      expect(swarmState().agents.find((info) => info.id === 'worker-1')!.state).toBe('invited');
      expect(pendingWorkerSpawns().map((worker) => worker.id)).toEqual(['worker-1']);

      // MAX_COMMANDS is 20. Every resume has a real durable continuation and is held by the
      // explicit automation pause. The continuation has no other dispatcher, while the worker
      // still has its durable invited row, so the twenty-first entry spills that untouched
      // worker transport safely.
      const resumptions: Array<{ sessionId: string; token: string }> = [];
      for (let n = 0; n < 20; n++) {
        const from = `${(0xc0c01000 + n).toString(16)}-1111-4222-8333-${n.toString(16).padStart(12, '0')}`;
        const continuation = await automaticCompactedSession(from, `worker spill handoff ${n}`);
        resumptions.push(continuation);
        queueResume(continuation.sessionId, continuation.token);
      }

      expect(pendingCommands().some((command) => command.what === `worker:${currentRunId()}:worker-1`)).toBe(false);
      expect(pendingCommands()).toHaveLength(20);

      expect(swarmState().running).toBe(true);
      const worker = swarmStateForCaller({ conversationId: PRIME_CHAT }).agents.find((info) => info.id === 'worker-1')!;
      expect(worker.state).toBe('invited');
      expect(worker.result).toBeNull();
      expect(pendingWorkerSpawns().map((entry) => entry.id)).toEqual(['worker-1']);

      // Freeing any browser slot immediately rehydrates the owed worker command; no restart or
      // second spawn request is needed.
      expect(cancelResume(resumptions[0]!.sessionId)).toBe(true);
      await vi.waitFor(() => expect(pendingCommands().some(
        (command) => command.what === `worker:${currentRunId()}:worker-1`
      )).toBe(true));
      expect(pendingCommands()).toHaveLength(20);
    } finally {
      await saveConfig(previous);
      applyAutomationPause(previous.ui.automationPaused === true);
    }
  });

  it('returns an untouched automatic overflow to its durable ticket instead of inventing attention custody', async () => {
    const previous = getConfig();
    try {
      await pair();
      await saveConfig({ ...previous, ui: { ...previous.ui, automationPaused: true } });
      applyAutomationPause(true);

      const queued: Array<{ sessionId: string; token: string; commandId: string }> = [];
      for (let n = 0; n < 21; n++) {
        const from = `${(0xc0c00000 + n).toString(16)}-1111-4222-8333-${n.toString(16).padStart(12, '0')}`;
        const continuation = await automaticCompactedSession(from, `automatic overflow handoff ${n}`);
        const command = queueResume(continuation.sessionId, continuation.token)!;
        queued.push({ ...continuation, commandId: command.id });
      }

      // MAX_COMMANDS is 20. The oldest command never crossed the browser handout boundary,
      // so its transport row may be retired while its safe awaiting-chat ticket remains.
      // That is backlog pressure, not a six-hour attention incident with no document owner.
      await vi.waitFor(() => expect(pendingCommands()).toHaveLength(20));
      const oldest = queued[0]!;
      expect(pendingCommands().some(entry => entry.id === oldest.commandId)).toBe(false);
      expect(continuationByToken(oldest.token)).toMatchObject({
        automatic: true,
        state: 'awaiting-chat',
        destinationSend: { state: 'not-attempted' }
      });
      expect(opened).toEqual([]);

      await flushDurable();
      let durable = await readDurable<any>('bridge-commands');
      expect(durable.commands).toHaveLength(20);
      expect(durable.commands.some((row: any) => row.phase === 'attention')).toBe(false);
      expect(durable.commands.some((row: any) => row.id === oldest.commandId)).toBe(false);

      // Freeing one transport slot replenishes that same durable continuation with a new id.
      // A new id is safe here precisely because no browser page or composer ever saw the old
      // one; the global pause proves replenishment itself cannot autonomously open a URL.
      expect(cancelResume(queued[1]!.sessionId)).toBe(true);
      await vi.waitFor(() => expect(pendingCommands().some(
        entry => entry.what === `resume:${oldest.sessionId}` && entry.id !== oldest.commandId
      )).toBe(true));
      expect(pendingCommands()).toHaveLength(20);
      expect(opened).toEqual([]);

      await flushDurable();
      durable = await readDurable<any>('bridge-commands');
      expect(durable.commands).toHaveLength(20);
      expect(durable.commands.some((row: any) => row.phase === 'attention')).toBe(false);
    } finally {
      resetBridgeForTests();
      await saveConfig(previous);
      applyAutomationPause(previous.ui.automationPaused === true);
    }
  });

