  it('requeues an exhausted pre-Send automatic resume under the same id while unrelated delivery continues', async () => {
    vi.useFakeTimers();
    const previous = getConfig();
    try {
      await pair();
      await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, limitAutomaticChats: true, maxActiveChats: 1 } });
      const continuation = await automaticCompactedSession(
        'c0c0c0c0-1111-4222-8333-000000000c04',
        'continue after an opening transport stalls'
      );
      // Record the independent source before the first replacement claim opens the recorder's
      // shadow-session collision gate. This regression is about command/admission isolation;
      // creating a brand-new unknown chat after the claim would correctly wait for that gate's
      // bounded window because it could itself be the still-arriving replacement destination.
      const unrelatedConversation = 'c0c0c0c0-1111-4222-8333-000000000c14';
      const unrelatedRecorded = await request('POST', '/events', {
        body: {
          conversationId: unrelatedConversation,
          events: [{ kind: 'user_message', time: Date.now(), text: 'do the work', messageId: `m-${unrelatedConversation}` }]
        }
      });
      const unrelatedSessionId = unrelatedRecorded.body.sessionId as string;
      expect(unrelatedSessionId).toBeTruthy();
      const command = queueResume(continuation.sessionId, continuation.token)!;
      await waitForOpened(1);
      await redeem(command.id, 'stalled-automatic-page');

      await vi.advanceTimersByTimeAsync(REDEEMED_COMMAND_DELIVERY_MS + 1);
      await vi.waitFor(() => expect(pendingCommands()).toEqual(expect.arrayContaining([
        expect.objectContaining({ id: command.id, lastError: expect.stringContaining('did not confirm delivery') })
      ])));
      await flushDurable();
      expect(continuationByToken(continuation.token)).toMatchObject({
        automatic: true,
        state: 'awaiting-chat',
        destinationSend: { state: 'not-attempted' }
      });
      expect((await readDurable<any>('bridge-commands')).commands).toEqual(expect.arrayContaining([
        expect.objectContaining({ id: command.id, phase: 'queued', owner: null, ownerTabLease: null })
      ]));
      expect(opened).toEqual([commandUrl(command.id)]);
      // Delayed transport retry is not active provider work. Another continuation can use the
      // configured single slot and must not remint the exhausted command.
      const unrelatedTicket = await openContinuationNow(unrelatedSessionId, unrelatedConversation, true);
      expect(await attachSummary(unrelatedTicket.token, `unrelated handoff keeps moving

${SAMPLE_BRIEF}`)).not.toBeNull();
      const unrelated = { sessionId: unrelatedSessionId, token: unrelatedTicket.token };
      const later = queueResume(unrelated.sessionId, unrelated.token)!;
      await vi.waitFor(() => expect(opened).toHaveLength(2));
      expect(opened[1]).toBe(commandUrl(later.id));
      expect(opened.filter(url => new URL(url).searchParams.get('clf') === command.id)).toHaveLength(1);

      // The old pre-Send document lost custody. A late receipt from it cannot commit the new
      // destination after the same marker was safely returned to the queue.
      const late = await request('POST', '/commands/ack', { body: {
        id: command.id,
        status: 'sent',
        conversationId: 'c0c0c0c0-1111-4222-8333-000000000c15',
        client: 'stalled-automatic-page'
      } });
      expect(late.status).toBe(409);
      expect(pendingCommands().some(entry => entry.id === command.id)).toBe(true);
    } finally {
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

