  it('does not attach a stale prepared payload to a command replaced during its durable freeze', async () => {
    await pair();
    const chat = '33333333-4444-5555-6666-777777777779';
    const older = await compactedSession(chat, 'older freeze-race brief');
    const first = queueResume(older.sessionId, older.token)!;
    const durable = await import('../src/main/durable.js'), write = durable.writeDurableNow, gate = faultGate();
    let held = false;
    const spy = vi.spyOn(durable, 'writeDurableNow').mockImplementation(async (name, value) => {
      const result = await write(name, value);
      const snapshot = value as { commands?: Array<{ id: string; preparedText?: string }> };
      if (name === 'bridge-commands' && !held && snapshot.commands?.some(row =>
          row.id === first.id && row.preparedText?.includes('older freeze-race brief'))) {
        held = true; await gate.hold();
      }
      return result;
    });
    try {
      const oldRedeem = request('POST', '/commands/redeem', { body: { id: first.id, client: 'freeze-old-page' } });
      await gate.entered;
      abortContinuation(older.token, 'explicit replacement during prompt persistence');
      const newerToken = await readyContinuation(older.sessionId, 'newer freeze-race brief', chat);
      const replacement = queueResume(older.sessionId, newerToken)!;
      expect(replacement.id).toBe(first.id);
      gate.release();
      expect((await oldRedeem).status).toBe(409);
      const next = await redeem(replacement.id, 'freeze-new-page');
      expect(next.text).toContain('newer freeze-race brief');
      expect(next.text).not.toContain('older freeze-race brief');
      const saved = await readDurable<{ commands: Array<{ id: string; preparedText?: string }> }>('bridge-commands');
      expect(saved?.commands.find(row => row.id === replacement.id)?.preparedText).toBe(next.text);
    } finally { gate.release(); spy.mockRestore(); }
  });

