  it('rechecks the same claimed unattributed recovery before mutation and retains a no-action deferral (#1874)', async () => {
    vi.useFakeTimers();
    try {
      await pair(); await events(PRIME, [openTurn('approval-after-claim')]);
      await unattributed(); await vi.advanceTimersByTimeAsync(15_000);
      const repair = await maintenance();
      const claim = (phase?: string) => request('POST', '/repairs/claim', {
        body: { token: repair!.token, ...(phase ? { phase } : {}) }
      });
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect((await claim()).body.allowed).toBe(true);
      expect((await claim('recheck')).body.allowed).toBe(true);
      await request('GET', `/activity?conversationId=${PRIME}&approval=1`);
      expect((await claim('recheck')).body.allowed).toBe(false);
      // The browser reports that it performed no action; only that existing receipt
      // owner may restore the unspent repair. A denied recheck alone is not replay authority.
      await request('GET', `/status?repairDeferred=${repair!.token}&repairCause=claim-revoked`);
      expect(await maintenance()).toBeNull();
      await request('GET', `/activity?conversationId=${PRIME}&approval=0`);
      await vi.advanceTimersByTimeAsync(15_000);
      const next = await maintenance();
      expect(next).toMatchObject({ conversationId: PRIME, reason: 'unattributed' });
      expect(next!.token).not.toBe(repair!.token);
      expect((await claim()).body.allowed).toBe(false);
    } finally { vi.useRealTimers(); }
  });

