  it('never accepts a forged pre-claim assistant-error browser ACK and holds a claimed receipt when a new native Core call opens', async () => {
    await pair();
    resetCoreBrowserEvidenceForTests();
    try {
      const userMessageId = randomUUID();
      await events(OTHER, [
        { kind: 'user_message', time: Date.now(), messageId: userMessageId, text: 'Retain the failed original question.' },
        openTurn('stream-native-claim'),
        { kind: 'chat_error', time: Date.now(), turnId: 'stream-native-claim',
          reason: 'stream_gone', recoverable: true, text: 'resume HTTP 404' }
      ]);
      const offered = await maintenance();
      expect(offered).toMatchObject({ conversationId: OTHER, reason: 'assistant-error' });
      const claim = () => request('POST', '/repairs/claim', { body: { token: offered!.token } });
      // The token is merely an offer until the browser positively claims it.
      // A late/forged receipt has no action authority.
      expect((await request('GET', `/status?repaired=${offered!.token}&repairAction=reloaded`)).status).toBe(200);
      expect((await claim()).body.allowed).toBe(true);
      const native = { documentId: 'stream-native-claim-document', navigationEpoch: 4,
        observedAt: Date.now(), shell: 'alternate', shellDiscovery: 'compatible',
        ordinaryFinal: { reason: 'open-call', questions: 1, calls: 1, openCalls: 1,
          codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false,
          sourceUserMessageId: userMessageId, coreCallMessageIds: ['native-unfinished-before-reload'],
          allCoreRequestIds: ['wfr_unfinished_before_reload'], openRequestIds: ['wfr_unfinished_before_reload'] } };
      const seen = await request('GET',
        `/activity?conversationId=${OTHER}&coreDiagnostic=${encodeURIComponent(JSON.stringify(native))}`);
      expect(seen.status).toBe(200);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(OTHER))?.reason).toBe('evidence');
      // The original claim was valid, but after a Chrome await the exact
      // provider has opened a native Core parent. Recheck grants NO fresh
      // permission; the companion must not reload before the parent settles.
      expect((await request('POST', '/repairs/claim', {
        body: { token: offered!.token, phase: 'recheck' }
      })).body.allowed).toBe(false);
      // Even after a valid claim, a delayed reported action must not turn
      // the newly opened tool's unknown result into a successful recovery.
      let nativeHoldLogged = false;
      const stopLog = onLog(line => {
        if (line.message.includes('assistant_repair_receipt_native_hold')) nativeHoldLogged = true;
      });
      try {
        expect((await request('GET', `/status?repaired=${offered!.token}&repairAction=reloaded`)).status).toBe(200);
        expect(nativeHoldLogged).toBe(true);
      } finally { stopLog(); }
      expect(await maintenance()).toBeNull();
    } finally { resetCoreBrowserEvidenceForTests(); }
  });

