      expect((await request('POST', '/repairs/claim', { body: { token: first!.token } })).body.allowed).toBe(true);
      await request('GET', `/status?repairDeferred=${encodeURIComponent(first!.token)}&repairCause=retry-not-ready`);
      expect(await maintenance()).toBeNull();
      const session = await findSessionByConversation(PRIME, { requireUnique: true });
      const progressBefore = await readEvents(session!.id, { kinds: ['progress'] });
      vi.setSystemTime(Date.now() + 15_001);
