  /**
   * Prime's own open turn is on the same silence clock as anybody else's.
   *
   * Prime is the chat a run is steered from, so it is the one whose stall nothing else is
   * watching: no worker slot depends on it and no bootstrap is waiting on it.
   */
  it.each(['ordinary', 'worker'] as const)('does not retire a newer %s turn when a spent silence sweep finishes late', async role => {
    const inputModule = await import('../src/main/session/input.js');
    const gate = faultGate();
    const previous = getConfig();
    let held: ReturnType<typeof vi.spyOn> | undefined;
    vi.useFakeTimers({ toFake: ['Date'] });
    try {
      await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, recoverAgentTabs: false } });
      await pair();
      if (role === 'worker') {
        spawn({ workers: [{ task: 'retain the renewed worker turn' }], caller: { conversationId: PRIME } });
        expect(bindConversation('worker-1', OTHER)).toBe(true);
      }
      await events(OTHER, [
        { kind: 'model_selection', time: Date.now(), model: 'GPT-5.6 Sol', reasoningEffort: 'high' },
        openTurn('spent-sweep-old')
      ]);
      await attributed(OTHER, false, Date.now());
      vi.setSystemTime(Date.now() + CHAT_SILENCE_MS + 1);

      // Recovery is Off, so this old grant is spent without a reload. Hold the
      // subsequent pickup await, then enable recovery for a real new turn.
      const original = inputModule.pendingQueuedPickups;
      held = vi.spyOn(inputModule, 'pendingQueuedPickups').mockImplementationOnce(async () => {
        await gate.hold();
        return original();
      });
      const sweeping = sweepStaleSwarm(Date.now());
      await gate.entered;
      await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, recoverAgentTabs: true } });
      await events(OTHER, [
        { kind: 'user_message', time: Date.now(), messageId: 'spent-sweep-question', text: 'Continue with the next step.' },
        { kind: 'model_selection', time: Date.now(), model: 'GPT-5.6 Sol', reasoningEffort: 'xhigh' },
        openTurn('spent-sweep-new')
      ]);
      await attributed(OTHER, false, Date.now());
      const session = (await findSessionByConversation(OTHER))!;
      const watched = (await sessionControlsFor(session.id)).recovery?.find(hold => hold.kind === 'silence');
      expect(watched, 'the new turn has its own silence grant').toBeDefined();

      gate.release();
      await sweeping;
      if (role === 'worker') expect(swarmState().agents.find(agent => agent.id === 'worker-1')?.state).toBe('active');
      expect((await sessionControlsFor(session.id)).recovery?.find(hold => hold.kind === 'silence'),
        'the old sweep cannot retire the new grant').toEqual(watched);
      const reloads = () => getLog().filter(entry => entry.message.includes('asking the browser to reload ' + OTHER)).length;
      const before = reloads();
      vi.setSystemTime(watched!.deadline + 1);
      await sweepStaleSwarm(Date.now());
      expect(reloads() - before).toBe(1);
    } finally {
      gate.release();
      held?.mockRestore();
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

