  it('does not mistake a late canonical revision of an older user message for work after the final', async () => {
    const previous = getConfig();
    await saveConfig({ ...previous, goal: { ...previous.goal, enabled: true, mode: 'loop' } });
    await setSecret('openRouterApiKey', 'sk-or-canonical-revision');
    resetGoalStateForTests();
    try {
      await pair();
      const turnId = 'turn-after-old-canonical-revision';
      const oldQuestion = {
        kind: 'user_message', time: Date.now(), messageId: 'old-canonical-question',
        text: 'The question that started before this completed turn.'
      };
      const opened = await events(OTHER, [
        oldQuestion,
        openTurn(turnId)
      ]);
      await attributed(OTHER, false, Date.now(), turnId);
      const recorded = await events(OTHER, [
        { kind: 'assistant_message', time: Date.now(), messageId: `answer-${turnId}`, turnId,
          text: 'The exact requested work is complete.', state: 'final', final: true, activeNow: false },
        endTurn(turnId, 'completed')
      ]);
      expect(recorded.body.sessionId).toBe(opened.body.sessionId);
      const before = await readEvents(recorded.body.sessionId);
      const final = before.findLast(event => event.kind === 'assistant_message' && event.turnId === turnId)!;
      const finalPosition = final.kind === 'assistant_message' ? (final.finalContentSeq ?? final.origin ?? final.seq) : 0;

      // Recorder enrichment rewrites the canonical row with a fresh storage seq while retaining
      // its original chronological position. That revision must not reopen the completed turn.
      await events(OTHER, [{ ...oldQuestion, reaction: '😂' }]);
      const after = await readEvents(recorded.body.sessionId);
      const revised = after.find(event => event.kind === 'user_message' && event.messageId === oldQuestion.messageId)!;
      if (revised.kind !== 'user_message') throw new Error('canonical user revision was not recorded');
      expect(revised.seq).toBeGreaterThan(finalPosition);
      expect(revised.origin).toBeLessThan(finalPosition);

      const drafted = await request('POST', '/goal/draft', {
        body: { conversationId: OTHER, turnId, clientId: 'tab-1' }
      });
      expect(drafted.status, JSON.stringify(drafted.body)).toBe(200);
    } finally {
      resetGoalStateForTests();
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
    }
  });

  it.each(['settled', 'running local tool', 'generating page'] as const)(
    'does not turn a drained Pro tool grant into a ten-minute Goal wait: %s', async state => {
    const previous = getConfig();
    await saveConfig({ ...previous, goal: { ...previous.goal, enabled: true, mode: 'loop' } });
    await setSecret('openRouterApiKey', 'sk-or-stale-grant');
    resetGoalStateForTests();
    let releaseTool = () => {};
    let heldTool: Promise<void> = Promise.resolve();
    try {
      await pair();
      const turnId = `stale-pro-grant-${state.replaceAll(' ', '-')}`;
      await events(OTHER, [
        { kind: 'model_selection', model: 'gpt-6-pro', reasoningEffort: 'pro', time: Date.now() },
        openTurn(turnId)
      ]);
      await attributed(OTHER, false, Date.now(), turnId);

      // Reproduce the lifecycle race directly at the recorder boundary: the canonical final
      // and end are durable, but bridge lifecycle has not yet retired the earlier MCP lease.
      const recorded = await recordChatObservations(OTHER, [{
        kind: 'assistant_message', time: Date.now(), messageId: `answer-${turnId}`, turnId,
        text: 'The exact requested work is complete.', state: 'final', final: true, activeNow: false
      }, { kind: 'turn_end', time: Date.now(), turnId, outcome: 'completed' }]);
      const durable = await readEvents(recorded.sessionId!);
      const final = durable.findLast(event => event.kind === 'assistant_message' && event.turnId === turnId)!;
      expect(final).toBeDefined();
      await acceptGoalReplyNow({ conversationId: OTHER, sessionId: recorded.sessionId!,
        replyId: `answer-${turnId}`, turnId, eventSeq: final.seq, blocked: false });

      if (state === 'running local tool') {
        const { trackInFlight, emptyEvidence } = await import('../src/main/mcp/call-context.js');
        heldTool = trackInFlight({ startedAt: Date.now(), transportKey: null, agent: null, outcome: null,
          evidence: emptyEvidence(), caller: { conversationId: OTHER, requestId: 'held-stale-grant-call', transportKey: null } },
          () => new Promise<void>(resolve => { releaseTool = resolve; }));
      } else if (state === 'generating page') {
        await recordChatObservations(OTHER, [{ kind: 'turn_start', time: Date.now(), turnId: `replacement-${turnId}` }]);
      }

      const controls = await sessionControlsFor(recorded.sessionId!);
      const drafted = await request('POST', '/goal/draft', { body: { conversationId: OTHER, turnId, clientId: 'tab-1' } });
      if (state === 'settled') {
        expect(controls.goalWait).toMatchObject({
          reason: 'pickup',
          detail: expect.stringContaining('sending is not confirmed')
        });
        expect(drafted.status).toBe(200);
      } else {
        expect(controls.goalWait?.reason).toBe(state === 'running local tool' ? 'tools' : 'quiet');
        expect(drafted.body).toMatchObject({ error: 'chat_still_working' });
      }
    } finally {
      releaseTool(); await heldTool;
      resetGoalStateForTests();
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
    }
  });

