  it('bounds a prolonged missing-Core Loop incident, exposes needs-attention, and resumes the same saved reply deliberately', async () => {
    const chat = 'c9595959-1111-2222-3333-444444444444';
    const goal = await import('../src/main/goal.js');
    const previous = getConfig();
    await saveConfig({ ...previous, goal: { ...previous.goal, enabled: true, mode: 'loop' } });
    await setSecret('openRouterApiKey', 'sk-or-loop-bounded-core-test');
    try {
      await pair();
      const recorded = await events(chat, [
        { kind: 'model_selection', model: 'GPT-5.6 Sol', reasoningEffort: 'high', time: Date.now() },
        openTurn('loop-core-outage'),
        { kind: 'assistant_message', turnId: 'loop-core-outage', messageId: 'loop-core-outage-final',
          time: Date.now(), text: 'This answer finished without a local tool call.', final: true,
          state: 'final', activeNow: true, goalEligible: true },
        endTurn('loop-core-outage', 'completed')
      ]);
      const sessionId = recorded.body.sessionId as string;
      const authoredUsersBefore = (await getSession(sessionId))?.userMessages ?? 0;
      const refused = await request('POST', '/goal/draft', { body: { conversationId: chat, turnId: 'loop-core-outage' } });
      expect(refused.body).toMatchObject({ error: 'loop_mcp_call_missing', retryable: true });
      const held = goal.snapshotGoalReplies().replies.find(row => row.conversationId === chat) as any;
      expect(held?.missingMcpDetectedAt).toEqual(expect.any(Number));

      coreConnection.state = 'offline';
      let retryAt = held.missingMcpRetryAt as number;
      const attentionAt = held.missingMcpDetectedAt + MISSING_MCP_LOOP_ATTENTION_MS;
      for (let attempt = 0; retryAt < attentionAt; attempt += 1) {
        const now = vi.spyOn(Date, 'now').mockReturnValue(retryAt);
        try {
          expect(await maintainLoopLanes(retryAt)).toBe(false);
        } finally {
          now.mockRestore();
        }
        const current = goal.snapshotGoalReplies().replies.find(row => row.conversationId === chat) as any;
        retryAt = current.missingMcpRetryAt;
        expect(coreConnectionRecovery).toHaveBeenCalledTimes(attempt + 1);
      }
      const attemptsAtAttention = coreConnectionRecovery.mock.calls.length;

      // Use the actual durable Goal file for the cold-process seam. The original incident
      // timestamps are authority: a restart may not mint a fresh five-minute window or turn the
      // exhausted ticket back into an automatic Core/browser retry.
      const persistedAtAttention = await readDurable<any>(GOAL_REPLIES_STATE);
      expect(persistedAtAttention?.replies).toEqual(expect.arrayContaining([
        expect.objectContaining({
          conversationId: chat,
          state: 'handled',
          missingMcpDetectedAt: held.missingMcpDetectedAt
        })
      ]));
      resetGoalStateForTests();
      goal.restoreGoalReplies(persistedAtAttention);
      resetBridgeForTests();
      setCoreConnectionStateProvider(() => coreConnection.state as 'connected' | 'offline');
      setCoreConnectionRecoveryProvider(coreConnectionRecovery);
      setBrowserOpener(async (url) => { opened.push(url); });
      await pair();
      expect(goal.missingMcpLoopRecoveryFor(chat, attentionAt)).toMatchObject({
        detectedAt: held.missingMcpDetectedAt,
        attentionAt,
        needsAttention: true
      });

      // Crossing the same ticket's attention deadline stops both automatic owners. It does not
      // erase or rephrase the reply, open another tab, or manufacture another user message.
      let now = vi.spyOn(Date, 'now').mockReturnValue(attentionAt);
      try {
        expect(await maintainLoopLanes(attentionAt)).toBe(false);
        const snapshot = await automationSupervisorSnapshot(undefined, attentionAt);
        expect(snapshot.chats.find(row => row.conversationId === chat)).toMatchObject({
          state: 'stalled',
          recoveryStage: 'core',
          recoverable: false,
          nextRetryAt: null,
          reason: expect.stringContaining('bounded automatic recovery window')
        });
        const stopped = await request('POST', '/goal/draft', { body: { conversationId: chat, turnId: 'loop-core-outage' } });
        expect(stopped.body).toMatchObject({ error: 'loop_mcp_recovery_needs_attention', retryable: false });
        expect(stopped.body.message).toContain('exact Loop reply is still saved');
      } finally {
        now.mockRestore();
      }
      expect(coreConnectionRecovery).toHaveBeenCalledTimes(attemptsAtAttention);
      expect(opened).toEqual([]);
      expect((await getSession(sessionId))?.userMessages).toBe(authoredUsersBefore);

      // Once Core is repaired, the existing deliberate Resume boundary re-arms this exact row.
      // It does not spawn/rebind a worker or synthesize a replacement conversation.
      coreConnection.state = 'connected';
      now = vi.spyOn(Date, 'now').mockReturnValue(attentionAt + 1);
      try {
        const resumed = await resumeAutomationChats({ startBrowser: false });
        expect(resumed.queued).toBe(1);
        expect(resumed.rearmed).toBe(1);
      } finally {
        now.mockRestore();
      }
      const rearmed = goalPendingReplyFor(chat);
      expect(rearmed).toMatchObject({ turnId: 'loop-core-outage' });
      expect((await getSession(sessionId))?.userMessages).toBe(authoredUsersBefore);
      expect(opened).toEqual([]);

      // Crash again after Resume all committed the exact pickup but before the page completed it.
      // Restoring that durable row must not reconstruct another reply or synthesize another user
      // turn. One browser recovery can be queued for the already-pending row; repeated Resume is
      // idempotent inside the restarted process.
      const persistedRearmed = await readDurable<any>(GOAL_REPLIES_STATE);
      expect(persistedRearmed?.replies).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId: chat, replyId: rearmed!.replyId, state: 'pending' })
      ]));
      expect(persistedRearmed?.replies.find((row: any) => row.conversationId === chat)).not.toHaveProperty('missingMcpDetectedAt');
      now = vi.spyOn(Date, 'now').mockReturnValue(attentionAt + 2);
      try {
        resetGoalStateForTests();
        goal.restoreGoalReplies(persistedRearmed);
        resetBridgeForTests();
        setCoreConnectionStateProvider(() => coreConnection.state as 'connected' | 'offline');
        setCoreConnectionRecoveryProvider(coreConnectionRecovery);
        setBrowserOpener(async (url) => { opened.push(url); });
        await pair();
        expect(goalPendingReplyFor(chat)).toMatchObject({
          replyId: rearmed!.replyId,
          turnId: rearmed!.turnId,
          acceptedAt: rearmed!.acceptedAt
        });
        const afterReload = await resumeAutomationChats({ startBrowser: false });
        expect(afterReload.rearmed).toBe(0);
        expect(afterReload.queued).toBe(1);
        expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({ queued: 0, rearmed: 0 });
      } finally {
        now.mockRestore();
      }
      expect((await getSession(sessionId))?.userMessages).toBe(authoredUsersBefore);
      expect(opened).toEqual([]);
    } finally {
      resetGoalStateForTests();
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
    }
  });

  it('does not let one slow Core recovery check starve unrelated durable Loop recovery', async () => {
    const missing = 'c9696969-1111-2222-3333-444444444444';
    const healthy = 'c9797979-1111-2222-3333-444444444444';
    const goal = await import('../src/main/goal.js');
    const previous = getConfig();
    let releaseCore: (state: 'connected' | 'offline') => void = () => undefined;
    vi.useFakeTimers({ toFake: ['Date'] });
    try {
      // Do not persist an Off override for every older fixture session: the full suite can contain
      // more than the production switch-ledger cap even though this fairness check owns only the
      // two fresh conversations below. Stale sessions have no current turn/reply and cannot enter
      // this fixture's exact recovery lane.
      await saveConfig({ ...previous, goal: { ...previous.goal, enabled: true, mode: 'loop' },
        multiAgent: { ...previous.multiAgent, maxActiveChats: 1 } });
      await setSecret('openRouterApiKey', 'sk-or-loop-core-fairness-test');
      await pair();
      const base = Date.now();
      await events(missing, [
        { kind: 'model_selection', model: 'GPT-5.6 Sol', reasoningEffort: 'high', time: base },
        openTurn('slow-core-turn')
      ]);
      await events(missing, [
        { kind: 'assistant_message', turnId: 'slow-core-turn', messageId: 'slow-core-final', time: base,
          text: 'Checkpoint complete.', final: true, state: 'final', activeNow: true, goalEligible: true },
        endTurn('slow-core-turn', 'completed')
      ]);
      const healthyStart = await events(healthy, [
        { kind: 'model_selection', model: 'GPT-5.6 Sol', reasoningEffort: 'high', time: base },
        openTurn('healthy-loop-turn')
      ]);
      await setGoalSwitchNow(healthy, 'loop', true, true);
      await recordToolCall({
        tool: 'read', args: { paths: ['/project/healthy-loop.ts'] }, content: [{ type: 'text', text: 'ok' }],
        outcome: 'ok', durationMs: 1, startedAt: base, conversationId: healthy,
        sessionId: healthyStart.body.sessionId as string
      });
      await events(healthy, [
        { kind: 'assistant_message', turnId: 'healthy-loop-turn', messageId: 'healthy-loop-final', time: base,
          text: 'Healthy checkpoint complete.', final: true, state: 'final', activeNow: true, goalEligible: true },
        endTurn('healthy-loop-turn', 'completed')
      ]);
      const refused = await request('POST', '/goal/draft', { body: { conversationId: missing, turnId: 'slow-core-turn' } });
      expect(refused.body).toMatchObject({ error: 'loop_mcp_call_missing', retryable: true });
      const ticket = goal.missingMcpLoopRecoveryFor(missing)!;
      expect(goalPendingReplyFor(healthy)).toMatchObject({ turnId: 'healthy-loop-turn' });

      coreConnection.state = 'offline';
      coreConnectionRecovery.mockImplementation(() => new Promise(resolve => { releaseCore = resolve; }));
      vi.setSystemTime(ticket.retryAt + 1);
      const pass = maintainLoopLanes(Date.now());
      await vi.waitFor(() => expect(coreConnectionRecovery).toHaveBeenCalledTimes(1));

      // The global transport is conclusively offline, so unrelated durable debt may be queued
      // but cannot grant a browser action. Missing-Core evidence for one source is not permission
      // to bypass the global lifecycle gate.
      expect((await request('GET', '/status')).body.repairs).toEqual([]);
      expect(goalPendingReplyFor(healthy)).toMatchObject({
        turnId: 'healthy-loop-turn', replyId: 'healthy-loop-final'
      });
      // Connection may publish actual transport readiness before its slower aggregate source
      // check finishes. That unresolved promise must not starve the healthy exact Loop lane.
      coreConnection.state = 'connected';
      applyCoreConnectionDispatchState('connected');
      await vi.waitFor(async () => {
        const repairs = (await request('GET', '/status')).body.repairs ?? [];
        expect(repairs).toEqual(expect.arrayContaining([
          expect.objectContaining({ conversationId: healthy, reason: 'automation' })
        ]));
      });
      expect(goal.missingMcpLoopRecoveryFor(missing)?.retryAt).toBe(ticket.retryAt);
      expect(coreConnectionRecovery).toHaveBeenCalledTimes(1);

      releaseCore('offline');
      await pass;
      await vi.waitFor(() => expect(goal.missingMcpLoopRecoveryFor(missing)?.retryAt).toBeGreaterThan(ticket.retryAt));
    } finally {
      releaseCore('offline');
      resetGoalStateForTests();
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

  it('converges mixed Loop recovery debt across one cold restore without duplicate work', async () => {
    const lost = 'f7111111-21a4-4111-8111-111111111111';
    const retryOne = 'f7222222-21a4-4111-8111-222222222222';
    const exhaustedCore = 'f7333333-21a4-4111-8111-333333333333';
    const exhaustedBrowser = 'f7444444-21a4-4111-8111-444444444444';
    const healthy = 'f7555555-21a4-4111-8111-555555555555';
    const stale = 'f7666666-21a4-4111-8111-666666666666';
    const retryTwo = 'f7777777-21a4-4111-8111-777777777777';
    const goal = await import('../src/main/goal.js');
    const previous = getConfig();
    const isolatedSessionRoot = path.join(dir, 'mixed-loop-cold-restore');
    vi.useFakeTimers({ toFake: ['Date'] });
    try {
      // This suite intentionally retains session folders across tests so restart cases can reopen
      // them. Global Loop makes every retained row visible, though, and this fixture's former
      // blanket Off pass legitimately filled the production 400-switch fence before it reached
      // its seven target chats. Give this cold-restore scenario its own session catalog instead of
      // weakening or bypassing that fence.
      await flushSessions();
      resetSessionStoreForTests();
      resetRecorderForTests();
      initSessionStore(isolatedSessionRoot);
      await saveConfig({
        ...previous,
        goal: { ...previous.goal, enabled: true, mode: 'loop' },
        multiAgent: { ...previous.multiAgent, limitAutomaticChats: false, maxActiveChats: 3 }
      });
      await setSecret('openRouterApiKey', 'sk-or-mixed-recovery-test');
      await pair();
      for (const chat of (await automationSupervisorSnapshot()).chats) await setSessionAutomation(chat.sessionId, 'off');

      const ownedFinal = async (conversationId: string, turnId: string, finalId: string, withMcp = false) => {
        const at = Date.now();
        const recorded = await events(conversationId, [
          { kind: 'user_message', messageId: `${turnId}-question`, text: `Continue ${turnId}`, time: at },
          { kind: 'model_selection', model: 'GPT-5.6 Sol', reasoningEffort: 'high', time: at },
          openTurn(turnId)
        ]);
        const sessionId = recorded.body.sessionId as string;
        await setGoalSwitchNow(conversationId, 'loop', true, true);
        if (withMcp) {
          await recordToolCall({
            tool: 'read', args: { paths: [`/project/${turnId}.ts`] }, content: [{ type: 'text', text: 'ok' }],
            outcome: 'ok', durationMs: 1, startedAt: at + 1, conversationId, sessionId
          });
        }
        await events(conversationId, [
          { kind: 'assistant_message', turnId, messageId: finalId, time: at + 2,
            text: `Finished ${turnId}.`, final: true, state: 'final', activeNow: true, goalEligible: true },
          endTurn(turnId, 'completed')
        ]);
        expect(goalPendingReplyFor(conversationId)).toMatchObject({ turnId, replyId: finalId });
        return sessionId;
      };

      const globalMissingCore = async (conversationId: string, turnId: string) => {
        const at = Date.now();
        const recorded = await events(conversationId, [
          { kind: 'user_message', messageId: `${turnId}-question`, text: `Continue ${turnId}`, time: at },
          { kind: 'model_selection', model: 'GPT-5.6 Sol', reasoningEffort: 'high', time: at },
          openTurn(turnId),
          { kind: 'assistant_message', turnId, messageId: `${turnId}-final`, time: at + 1,
            text: `Finished ${turnId} without Core.`, final: true, state: 'final', activeNow: true, goalEligible: true },
          endTurn(turnId, 'completed')
        ]);
        const refused = await request('POST', '/goal/draft', { body: { conversationId, turnId } });
        expect(refused.body).toMatchObject({ error: 'loop_mcp_call_missing', retryable: true });
        const ticket = goal.missingMcpLoopRecoveryFor(conversationId)!;
        expect(ticket).toMatchObject({ conversationId, sessionId: recorded.body.sessionId, turnId });
        return { sessionId: recorded.body.sessionId as string, ticket };
      };

      // First create one real bounded browser-repair exhaustion. Its durable fence is the
      // browser-failure member of the mixed set and must survive the cold process seam below.
      const browserSession = await ownedFinal(exhaustedBrowser, 'mixed-browser-turn', 'mixed-browser-final');
      expect(await resumeAutomationChats({ startBrowser: false, maxQueued: 1 })).toMatchObject({ queued: 1 });
      let [browserRepair] = ((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
        entry.conversationId === exhaustedBrowser);
      expect(browserRepair).toMatchObject({ reason: 'automation' });
      await request('GET', `/status?repaired=${browserRepair.token}&repairAction=reloaded`);
      vi.setSystemTime(Date.now() + 25_001);
      [browserRepair] = ((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
        entry.conversationId === exhaustedBrowser);
      expect(browserRepair).toMatchObject({ reason: 'automation' });
      await request('GET', `/status?repaired=${browserRepair.token}&repairAction=reloaded`);
      vi.setSystemTime(Date.now() + 25_001);
      expect(((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
        entry.conversationId === exhaustedBrowser)).toEqual([]);
      expect((await automationSupervisorSnapshot()).chats.find(row => row.conversationId === exhaustedBrowser)).toMatchObject({
        state: 'stalled', recoveryStage: null, recoverable: true, spinning: false, nextRetryAt: null
      });

      // One older global Loop incident will already be exhausted when the two younger tickets
      // become due. It must stay dormant while those two share one canonical Core check.
      const exhausted = await globalMissingCore(exhaustedCore, 'mixed-exhausted-core-turn');

      // The remaining set is created while that incident clock is running: exact lost debt,
      // healthy pending debt, and a canonical final fenced by a newer semantic user boundary.
      const lostSession = await ownedFinal(lost, 'mixed-lost-turn', 'mixed-lost-final');
      const healthySession = await ownedFinal(healthy, 'mixed-healthy-turn', 'mixed-healthy-final', true);
      const staleSession = await ownedFinal(stale, 'mixed-stale-turn', 'mixed-stale-final');
      await events(stale, [{
        kind: 'user_message', messageId: 'mixed-stale-newer-user', text: 'A newer instruction supersedes that final.', time: Date.now() + 3
      }]);

      vi.setSystemTime(exhausted.ticket.detectedAt + 4 * 60_000 + 30_000);
      const retryA = await globalMissingCore(retryOne, 'mixed-retry-core-one');
      const retryB = await globalMissingCore(retryTwo, 'mixed-retry-core-two');
      vi.setSystemTime(Math.max(retryA.ticket.retryAt, retryB.ticket.retryAt) + 1);
      const mixedNow = Date.now();
      expect(goal.missingMcpLoopRecoveryFor(exhaustedCore, mixedNow)?.needsAttention).toBe(true);
      expect(goal.missingMcpLoopRecoveryFor(retryOne, mixedNow)?.needsAttention).toBe(false);
      expect(goal.missingMcpLoopRecoveryFor(retryTwo, mixedNow)?.needsAttention).toBe(false);

      const userCounts = new Map<string, number>();
      for (const sessionId of [browserSession, exhausted.sessionId, lostSession, healthySession, staleSession,
        retryA.sessionId, retryB.sessionId]) {
        userCounts.set(sessionId, (await getSession(sessionId))?.userMessages ?? -1);
      }

      // Model one cold restart where the small Goal ledger lost only the two rows whose exact
      // canonical history must decide recoverability. All other tickets and the exhausted browser
      // fence are read from their real durable stores.
      await flushDurable();
      const durableReplies = await readDurable<any>(GOAL_REPLIES_STATE);
      expect(durableReplies?.replies).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId: lost }),
        expect.objectContaining({ conversationId: stale }),
        expect.objectContaining({ conversationId: exhaustedCore, state: 'handled' }),
        expect.objectContaining({ conversationId: retryOne, state: 'handled' }),
        expect.objectContaining({ conversationId: retryTwo, state: 'handled' })
      ]));
      await writeDurableNow(GOAL_REPLIES_STATE, {
        ...durableReplies,
        savedAt: mixedNow,
        replies: durableReplies.replies.filter((row: any) => ![lost, stale].includes(row.conversationId))
      });
      const durableSwitches = await readDurable<any>(GOAL_SWITCHES_STATE);
      const durableCommands = await readDurable<any>('bridge-commands');
      expect(durableCommands?.recoveryFences).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId: exhaustedBrowser })
      ]));

      resetGoalStateForTests();
      goal.restoreGoalSwitches(durableSwitches);
      goal.restoreGoalReplies(await readDurable<any>(GOAL_REPLIES_STATE));
      resetBridgeForTests();
      setCoreConnectionStateProvider(() => coreConnection.state as 'connected' | 'offline');
      setCoreConnectionRecoveryProvider(coreConnectionRecovery);
      setBrowserOpener(async (url) => { opened.push(url); });
      await restoreCommands();
      await pair();
      expect(goalPendingReplyFor(lost)).toBeNull();
      expect(goalPendingReplyFor(stale)).toBeNull();

      coreConnection.state = 'offline';
      coreConnectionRecovery.mockClear();
      const retryOneBefore = goal.missingMcpLoopRecoveryFor(retryOne, mixedNow)!.retryAt;
      const retryTwoBefore = goal.missingMcpLoopRecoveryFor(retryTwo, mixedNow)!.retryAt;
      const exhaustedRetryBefore = goal.missingMcpLoopRecoveryFor(exhaustedCore, mixedNow)!.retryAt;
      expect(await maintainLoopLanes(mixedNow)).toBe(true);

      // The two due retryable incidents share one Connection request. The exhausted Core ticket
      // stays dormant, while unrelated exact Loop debt is reconstructed/queued in the same pass.
      expect(coreConnectionRecovery).toHaveBeenCalledTimes(1);
      expect(goal.missingMcpLoopRecoveryFor(retryOne, mixedNow)?.retryAt).toBeGreaterThan(retryOneBefore);
      expect(goal.missingMcpLoopRecoveryFor(retryTwo, mixedNow)?.retryAt).toBeGreaterThan(retryTwoBefore);
      expect(goal.missingMcpLoopRecoveryFor(exhaustedCore, mixedNow)?.retryAt).toBe(exhaustedRetryBefore);
      expect(goalPendingReplyFor(lost)).toMatchObject({ replyId: 'mixed-lost-final', turnId: 'mixed-lost-turn' });
      expect(goalPendingReplyFor(stale)).toBeNull();

      const mixedSnapshot = await automationSupervisorSnapshot(undefined, mixedNow);
      expect(mixedSnapshot.chats.find(row => row.conversationId === exhaustedCore)).toMatchObject({
        state: 'stalled', recoveryStage: 'core', recoverable: false, spinning: false, nextRetryAt: null
      });
      expect(mixedSnapshot.chats.find(row => row.conversationId === exhaustedBrowser)).toMatchObject({
        state: 'stalled', recoveryStage: null, recoverable: true, spinning: false, nextRetryAt: null
      });
      for (const chat of [retryOne, retryTwo]) {
        expect(mixedSnapshot.chats.find(row => row.conversationId === chat)).toMatchObject({
          state: 'recovering', recoveryStage: 'core', recoverable: false
        });
      }

      expect((await request('GET', '/status')).body.repairs).toEqual([]);
      expect(goalPendingReplyFor(lost)).toMatchObject({ replyId: 'mixed-lost-final', turnId: 'mixed-lost-turn' });
      expect(goalPendingReplyFor(healthy)).toMatchObject({ replyId: 'mixed-healthy-final', turnId: 'mixed-healthy-turn' });
      // The same reconstructed/queued obligations become handout-eligible only after Connection
      // actually reports connected; a recovery deadline or returned promise is not that proof.
      coreConnection.state = 'connected';
      applyCoreConnectionDispatchState('connected');
      const repairs = (await request('GET', '/status')).body.repairs ?? [];
      expect(repairs).toHaveLength(1);
      expect([lost, healthy]).toContain(repairs[0].conversationId);
      expect(repairs[0].reason).toBe('automation');
      expect(await maintainLoopLanes(mixedNow)).toBe(false);
      expect(coreConnectionRecovery).toHaveBeenCalledTimes(1);

      // After Core is repaired, deliberate Resume all re-arms only exact still-current saved work
      // and releases the one exhausted browser fence. Calling it again is idempotent; the stale
      // newer-user chat remains fenced and no authored user row is synthesized anywhere.
      coreConnection.state = 'connected';
      const resumed = await resumeAutomationChats({ startBrowser: false });
      expect(resumed.rearmed).toBe(3);
      expect(resumed.queued).toBe(4);
      expect(goalPendingReplyFor(stale)).toBeNull();
      for (const chat of [retryOne, retryTwo, exhaustedCore]) expect(goal.missingMcpLoopRecoveryFor(chat)).toBeNull();
      expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({ queued: 0, rearmed: 0 });

      for (const [sessionId, count] of userCounts) expect((await getSession(sessionId))?.userMessages).toBe(count);
      expect(opened).toEqual([]);
    } finally {
      coreConnection.state = 'connected';
      resetGoalStateForTests();
      await flushSessions();
      resetRecorderForTests();
      resetSessionStoreForTests();
      initSessionStore(sessionCaseRoot);
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

  it('applies fail-closed backpressure when bounded automation recovery fence capacity is full', async () => {
    const first = 'd8181818-1111-4111-8111-818181818181';
    const second = 'd8282828-1111-4111-8111-828282828282';
    const previous = getConfig();
    vi.useFakeTimers({ toFake: ['Date'] });
    try {
      setRecoveryBookkeepingLimitForTests(1);
      await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, limitAutomaticChats: false, maxActiveChats: 2 } });
      await setSecret('openRouterApiKey', 'test-recovery-backpressure-key');
      await pair();
      for (const chat of (await automationSupervisorSnapshot()).chats) await setSessionAutomation(chat.sessionId, 'off');

      for (const [index, chat] of [first, second].entries()) {
        const turnId = `backpressure-turn-${index}`;
        await events(chat, [
          { kind: 'user_message', messageId: `backpressure-question-${index}`, text: `Keep case ${index} moving`, time: Date.now() },
          openTurn(turnId)
        ]);
        await setGoalSwitchNow(chat, 'loop', true, true);
        await events(chat, [
          { kind: 'assistant_message', messageId: `backpressure-final-${index}`, turnId,
            text: 'Ready for the next pass.', state: 'final', final: true, goalEligible: true, time: Date.now() },
          endTurn(turnId, 'completed')
        ]);
      }

      // Capacity one admits exactly one bounded browser episode even though both replies are
      // eligible. Repeated scheduling cannot oversubscribe the durable-fence capacity.
      expect(await resumeAutomationChats({ startBrowser: false, maxQueued: 2 })).toMatchObject({ eligible: 2, queued: 1 });
      let repairs = (await request('GET', '/status')).body.repairs ?? [];
      expect(repairs).toHaveLength(1);
      const owner = repairs[0].conversationId as string;
      const blocked = owner === first ? second : first;
      await request('GET', `/status?repaired=${repairs[0].token}&repairAction=reloaded`);
      vi.setSystemTime(Date.now() + 25_001);
      repairs = (await request('GET', '/status')).body.repairs ?? [];
      expect(repairs).toHaveLength(1);
      expect(repairs[0].conversationId).toBe(owner);
      await request('GET', `/status?repaired=${repairs[0].token}&repairAction=reloaded`);
      vi.setSystemTime(Date.now() + 25_001);
      expect((await request('GET', '/status')).body.repairs ?? []).toEqual([]);
      await flushDurable();
      expect((await readDurable<any>('bridge-commands'))?.recoveryFences).toEqual([
        expect.objectContaining({ conversationId: owner })
      ]);
      expect(await resumeAutomationChats({ startBrowser: false, maxQueued: 2 })).toMatchObject({ queued: 0 });
      expect((await request('GET', '/status')).body.repairs ?? []).toEqual([]);

      // Exact new work is the existing episode boundary. It frees the reserved slot, after which
      // the sibling can progress without evicting or silently forgetting any recovery authority.
      await events(owner, [
        { kind: 'user_message', messageId: 'backpressure-owner-new-question', text: 'Start a new exact turn.', time: Date.now() },
        openTurn('backpressure-owner-new-turn')
      ]);
      expect(await resumeAutomationChats({ startBrowser: false, maxQueued: 1 })).toMatchObject({ queued: 1 });
      repairs = (await request('GET', '/status')).body.repairs ?? [];
      expect(repairs).toHaveLength(1);
      expect(repairs[0].conversationId).toBe(blocked);
    } finally {
      setRecoveryBookkeepingLimitForTests(null);
      resetGoalStateForTests();
      await setSecret('openRouterApiKey', '');
      await saveConfig(previous);
      vi.useRealTimers();
    }
  });

