  it('repairs Goal onto the exact pre-fix resume-shadow chat and can draft there', async () => {
    await pair();
    const from = 'cafe0031-0000-4000-8000-000000000031';
    const to = 'cafe0032-0000-4000-8000-000000000032';
    const source = await createSession({ title: 'prime before resume-shadow collision', conversationId: from });
    spawn({ workers: [{ task: 'keep one worker alive across the broken resume' }], caller: { conversationId: from } });
    setGoalObjective(from, 'finish the release from the resumed prime chat');

    const openedContinuation = await openContinuationNow(source.id, from);
    const handoff = await attachSummary(openedContinuation.token, SAMPLE_BRIEF);
    expect(handoff).not.toBeNull();
    await claimContinuationNow(openedContinuation.token, 'resume-shadow-owner');
    const shadow = await createSession({
      title: 'Resumed · prime before resume-shadow collision',
      conversationId: to,
      origin: { kind: 'resume', fromSessionId: source.id, agentId: null, task: '' }
    });
    await recordChatObservations(to, [
      {
        kind: 'user_message',
        time: Date.now(),
        text: resumeBootstrapText(handoff!.text).replace('previous chat', `previous\u00c2\u00a0chat`),
        messageId: 'm-shadow-resume'
      },
      {
        kind: 'assistant_message',
        time: Date.now() + 1,
        text: 'The release is still unfinished.',
        messageId: 'a-shadow-resume',
        state: 'final',
        final: true
      }
    ]);
    expect(await commitContinuation(openedContinuation.token, to)).toBe(false);
    abortContinuation(openedContinuation.token, 'the replacement chat already belongs to another local session');
    expect(goalObjectiveFor(from)).toBe('finish the release from the resumed prime chat');
    expect(goalObjectiveFor(to)).toBe('');

    setContinuationRecoveryHooks({ repairPrimeTransfer: repairPrimeConversationAfterRecovery });

    // `/activity` must not turn a plausible-looking resume origin into takeover authority. The
    // exact bootstrap is the second half of the proof and this chat deliberately does not have it.
    const unrelated = 'cafe0033-0000-4000-8000-000000000033';
    await createSession({
      title: 'resume-looking but unrelated',
      conversationId: unrelated,
      origin: { kind: 'resume', fromSessionId: source.id, agentId: null, task: '' }
    });
    await recordChatObservations(unrelated, [
      { kind: 'user_message', time: Date.now(), text: 'a different bootstrap', messageId: 'm-unrelated-shadow' }
    ]);
    const unrelatedFeed = await request('GET', `/activity?conversationId=${unrelated}`);
    expect(unrelatedFeed.status).toBe(200);
    expect(unrelatedFeed.body.goal.objective).toBe('');
    expect(goalObjectiveFor(from)).toBe('finish the release from the resumed prime chat');
    expect(goalObjectiveFor(unrelated)).toBe('');

    // No agents/tool call performs the repair. The Goal activity poll itself must heal A→B.
    const feed = await request('GET', `/activity?conversationId=${to}`);
    expect(feed.status).toBe(200);
    expect(feed.body.sessionId).toBe(shadow.id);
    expect(feed.body.goal).toMatchObject({ enabled: true, objective: 'finish the release from the resumed prime chat' });
    expect(goalObjectiveFor(from)).toBe('');
    expect(goalObjectiveFor(to)).toBe('finish the release from the resumed prime chat');

    let calls = 0;
    const realFetch = globalThis.fetch;
    globalThis.fetch = (async () => {
      calls++;
      return Response.json({
        choices: [{ message: { content: JSON.stringify({ action: 'continue', reply: 'keep going from B' }) } }]
      });
    }) as never;
    try {
      await recordFinalForTest(to, 'g-shadow-repaired');
      const drafted = await request('POST', '/goal/draft', {
        body: { conversationId: to, turnId: 'g-shadow-repaired', clientId: 'shadow-goal-tab' }
      });
      expect(drafted.status).toBe(200);
      expect(drafted.body.sessionId).toBe(shadow.id);
      expect(drafted.body.goal.turnId).toBe('g-shadow-repaired');
      await vi.waitFor(() => expect(calls).toBe(1));
    } finally {
      globalThis.fetch = realFetch;
    }
  });

  it.each(['retained', 'expired', 'newer-ended-source', 'race-ended-source', 'wrong-source', 'wrong-generation', 'legacy-brief'] as const)(
    'fences the already-Goal-bound legacy source through real activity after its turn ended (%s)', async shape => {
      await pair();
      const suffix = `00000000005${['retained', 'expired', 'newer-ended-source', 'race-ended-source', 'wrong-source', 'wrong-generation', 'legacy-brief'].indexOf(shape)}`;
      const from = `cafe0051-0000-4000-8000-${suffix}`;
      const to = `cafe0052-0000-4000-8000-${suffix}`;
      const source = await createSession({ title: 'old already-projected source', conversationId: from });
      await sessionStoreModule.appendEvent(source.id, { kind: 'turn_start', source: 'extension', time: Date.now(), turnId: 'original-source-turn' });
      const ticket = await openContinuationNow(source.id, from);
      const handoff = await attachSummary(ticket.token, SAMPLE_BRIEF);
      await claimContinuationNow(ticket.token, 'old-projection-owner');
      const target = await createSession({ conversationId: to,
        origin: { kind: 'resume', fromSessionId: source.id, agentId: null, task: '' } });
      await recordChatObservations(to, [{ kind: 'user_message', time: Date.now(),
        text: resumeBootstrapText(handoff!.text), messageId: 'exact-already-projected-bootstrap' }]);
      // Model the old build, not the upgraded commit: the collision was aborted and Goal moved,
      // while the source generation ended without a durable refusal. Its real handoff survives.
      abortContinuation(ticket.token, 'the replacement chat already belongs to another local session');
      await sessionStoreModule.appendEvent(source.id, { kind: 'turn_end', source: 'extension', time: Date.now(), turnId: 'original-source-turn', outcome: 'completed' });
      setGoalObjective(to, 'retain the whole original task on this replacement');
      await setGoalSwitchNow(to, 'loop', true, true);
      if (shape !== 'retained') resetContinuationsForTests();
      if (shape === 'wrong-source' || shape === 'wrong-generation' || shape === 'legacy-brief') {
        const file = path.join(sessionStoreModule.sessionsRoot(), source.id, 'handoffs', `${handoff!.id}.json`);
        const stored = JSON.parse(await fs.readFile(file, 'utf8'));
        if (shape === 'wrong-source') stored.provenance.sourceConversationId = 'foreign-source';
        if (shape === 'wrong-generation') stored.provenance.sourceGeneration++;
        if (shape === 'legacy-brief') { delete stored.version; delete stored.provenance; }
        await fs.writeFile(file, JSON.stringify(stored), 'utf8');
      }
      if (shape === 'newer-ended-source') {
        // Storage order, not a wall-clock comparison, proves genuinely newer source work.
        await sessionStoreModule.appendEvent(source.id, { kind: 'turn_start', source: 'extension', time: 1, turnId: 'new-source-turn' });
        await sessionStoreModule.appendEvent(source.id, { kind: 'turn_end', source: 'extension', time: 2, turnId: 'new-source-turn', outcome: 'completed' });
      }
      expect((await getSession(source.id))?.activeTurnId).toBeNull();
      expect((await getSession(source.id))?.autoCompactionRefusal).toBeUndefined();
      if (shape === 'race-ended-source') {
        const refuse = sessionStoreModule.refuseAutomaticCompactionNow;
        const race = vi.spyOn(sessionStoreModule, 'refuseAutomaticCompactionNow').mockImplementationOnce(async (...args) => {
          await sessionStoreModule.appendEvent(source.id, { kind: 'turn_start', source: 'extension', time: 1, turnId: 'racing-new-source' });
          await sessionStoreModule.appendEvent(source.id, { kind: 'turn_end', source: 'extension', time: 2, turnId: 'racing-new-source', outcome: 'completed' });
          await refuse(...args);
        });
        onTestFinished(() => race.mockRestore());
      }
      const feed = await request('GET', `/activity?conversationId=${to}`);
      expect(feed.status).toBe(200);
      expect(feed.body.sessionId).toBe(target.id);
      expect(feed.body.goal.objective).toBe('retain the whole original task on this replacement');
      const expectedFence = shape === 'retained' || shape === 'expired'
        ? { conversationId: from, turnId: 'original-source-turn' } : undefined;
      expect((await getSession(source.id))?.autoCompactionRefusal).toEqual(expectedFence);
      await sessionStoreModule.flushSessions();
      await resetSessionStoreForTests();
      expect((await getSession(source.id))?.autoCompactionRefusal).toEqual(expectedFence);
      const fence = vi.spyOn(sessionStoreModule, 'refuseAutomaticCompactionNow');
      fence.mockClear();
      onTestFinished(() => fence.mockRestore());
      expect((await request('GET', `/activity?conversationId=${to}`)).status).toBe(200);
      expect(fence).not.toHaveBeenCalled();
      expect(goalObjectiveFor(from)).toBe('');
      expect(goalObjectiveFor(to)).toBe('retain the whole original task on this replacement');
      expect((await getSession(source.id))?.conversationId).toBe(from);
      expect((await getSession(target.id))?.conversationId).toBe(to);
    }
  );

