      expect((await report(open)).status).toBe(200);
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect(goalPendingReplyFor(chat)).toMatchObject(original!);
      expect((await report({ ...open, reason: 'associated', openCodeCalls: 0,
        openCodeCallMessageIds: [], answeredCodeCallMessageIds: [parent] })).status).toBe(200);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(chat))).toBeNull();
      expect((await claim('recheck')).body.allowed).toBe(true);
      expect((await claim()).body.allowed).toBe(false);
      expect(goalPendingReplyFor(chat)).toMatchObject(original!);
      // An authenticated Chrome 'nudged' receipt attests only to collection
