  it('does not settle an unclaimed or newly native-blocked Goal recovery from a late Chrome action receipt', async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    const chat = 'cafe01ab-0000-4000-8000-0000000001ab';
    const originalUserMessage = 'fbababab-1234-4234-8234-123456789ac4';
    const originalParent = 'goal-ack-guard-original-code-parent';
    const logger = await import('../src/main/logger.js');
    logger.initLogFile(path.join(dir, 'goal-action-ack-custody', 'app.log'));
    try {
      await pair();
      resetCoreBrowserEvidenceForTests();
      const opened = await request('POST', '/events', { body: { conversationId: chat, events: [
        { kind: 'user_message', messageId: originalUserMessage, text: 'Continue the saved work once.', time: Date.now() },
        { kind: 'turn_start', turnId: 'g-ack-guard', time: Date.now() },
        { kind: 'turn_end', turnId: 'g-ack-guard', outcome: 'completed', time: Date.now() },
        { kind: 'assistant_message', messageId: 'a-ack-guard', turnId: 'g-ack-guard',
          text: 'First part complete.', state: 'final', final: true, goalEligible: true, activeNow: true, time: Date.now() }
      ] } });
      expect(opened.status).toBe(200);
      const original = goalPendingReplyFor(chat);
      expect(original).toMatchObject({ replyId: 'a-ack-guard', sessionId: opened.body.sessionId });
      vi.setSystemTime(Date.now() + 60_000);
      await sweepStaleSwarm(Date.now());
      const offered = (await request('GET', '/status')).body.repairs?.find(
        (row: { conversationId: string }) => row.conversationId === chat);
      expect(offered).toMatchObject({ conversationId: chat, reason: 'goal', requiresClaim: true });
      const claim = (phase?: string) => request('POST', '/repairs/claim', { body: {
        token: offered.token, ...(phase ? { phase } : {})
      } });
      const report = (ordinaryFinal: Record<string, unknown>) => request('GET',
        `/activity?conversationId=${chat}&coreDiagnostic=${encodeURIComponent(JSON.stringify({
          documentId: 'goal-ack-guard-original-doc', navigationEpoch: 4, shell: 'alternate',
          shellDiscovery: 'compatible', observedAt: Date.now(), ordinaryFinal
        }))}`);
      // A successful HTTP status call is not a browser claim. Preserve the
      // original handout so its still-unclaimed token remains claimable.
      expect((await request('GET', `/status?repaired=${offered.token}&repairAction=nudged`)).status).toBe(200);
      expect((await request('GET', `/status?repaired=${offered.token}&repairAction=nudged`)).status).toBe(200);
      await logger.flushLocalIncidents();
      const earlyIncidents = (await logger.listLocalIncidents()).incidents.filter(row =>
        row.conversationId === chat && row.reason === 'goal_repair_receipt_before_claim');
      expect(earlyIncidents).toHaveLength(1);
      expect(earlyIncidents[0]).toMatchObject({ status: 'unresolved', sessionId: opened.body.sessionId,
        turnId: 'g-ack-guard', requestId: null, sendEvidence: 'not_observed', occurrences: 1 });
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect((await claim()).body.allowed).toBe(true);
      expect((await claim()).body.allowed).toBe(false);
      expect((await claim('recheck')).body.allowed).toBe(true);
      const open = { reason: 'open-code', questions: 1, calls: 0, openCalls: 0,
        codeCalls: 1, openCodeCalls: 1, activeTurnMapped: false, sourceUserMessageId: originalUserMessage,
        codeCallMessageIds: [originalParent], openCodeCallMessageIds: [originalParent],
        answeredCodeCallMessageIds: [] };
      expect((await report(open)).status).toBe(200);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(chat))?.reason).toBe('evidence');
      // A delayed browser reload/nudge receipt cannot erase a newer open
      // Code Mode parent or call the original Goal done.
      expect((await request('GET', `/status?repaired=${offered.token}&repairAction=nudged`)).status).toBe(200);
      await logger.flushLocalIncidents();
      const incidentRows = (await logger.listLocalIncidents()).incidents.filter(row =>
        row.conversationId === chat);
      expect(incidentRows).toContainEqual(expect.objectContaining({
        source: 'app', reason: 'goal_repair_receipt_native_hold', status: 'unresolved',
        sessionId: opened.body.sessionId, turnId: 'g-ack-guard', requestId: null,
        sendEvidence: 'not_observed',
        nativeCompletion: expect.objectContaining({ openCodeCalls: 1 }) }));
      expect(JSON.stringify(incidentRows)).not.toMatch(/goal-ack-guard-original-code-parent|a-ack-guard|Continue the saved work once|goal-action-ack-custody/);
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect(goalPendingReplyFor(chat)).toMatchObject(original!);
      expect((await report({ ...open, reason: 'associated', openCodeCalls: 0,
        openCodeCallMessageIds: [], answeredCodeCallMessageIds: [originalParent] })).status).toBe(200);
      expect(nativeFinalEvidenceWait(coreBrowserEvidence(chat))).toBeNull();
      // That result cannot retrospectively authorize the browser action
      // already reported while its original parent was still unresolved.
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect((await request('GET', `/status?repaired=${offered.token}&repairAction=nudged`)).status).toBe(200);
      expect((await claim('recheck')).body.allowed).toBe(false);
      expect(goalPendingReplyFor(chat)).toMatchObject(original!);
      await flushDurable();
      expect((await readDurable<any>('bridge-commands'))?.recoveryFences).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId: chat })
      ]));
      // Cold Main restart must restore that same ambiguous-action fence.
      // The durable Goal reply remains owed, but neither the old token nor
      // a newly invented pickup is entitled to replay a possibly acted tab.
      const owedBeforeRestart = snapshotGoalReplies();
      resetBridgeForTests();
      await restoreCommands();
      await pair();
      restoreGoalReplies(owedBeforeRestart);
      vi.setSystemTime(Date.now() + 25_001);
      await sweepStaleSwarm(Date.now());
      expect((await request('GET', '/status')).body.repairs?.filter(
        (row: { conversationId: string }) => row.conversationId === chat)).toEqual([]);
      expect(goalPendingReplyFor(chat)).toMatchObject(original!);
      await logger.flushLocalIncidents();
      expect((await logger.listLocalIncidents()).incidents.find(row =>
        row.conversationId === chat && row.reason === 'goal_repair_receipt_native_hold')?.status).toBe('unresolved');
    } finally {
      await logger.flushLocalIncidents();
      await logger.flushLogFile();
      logger.resetLoggerForTests();
      resetCoreBrowserEvidenceForTests();
      vi.useRealTimers();
    }
  });

