it('stages every Resume-all root but hands out only configured capacity and replenishes after a slot is free', async () => {
  const previous = getConfig();
  vi.useFakeTimers({ toFake: ['Date'] });
  try {
    await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, limitAutomaticChats: true, maxActiveChats: 1 } });
    await setSecret('openRouterApiKey', 'test-resume-all-key');
    await pair();
    const chats = [
      'a6666666-1111-4111-8111-000000000006',
      'a7777777-1111-4111-8111-000000000007'
    ];
    const sessionIds: string[] = [];
    for (const [index, chat] of chats.entries()) {
      const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
        { kind: 'user_message', messageId: `resume-question-${index}`, text: 'Keep this loop working', time: Date.now() + index },
        { kind: 'turn_start', turnId: `resume-finished-${index}`, time: Date.now() + index },
        { kind: 'assistant_message', messageId: `resume-final-${index}`, turnId: `resume-finished-${index}`, text: 'Paused at a safe checkpoint.', state: 'final', final: true, goalEligible: true, time: Date.now() + index },
        { kind: 'turn_end', turnId: `resume-finished-${index}`, outcome: 'completed', time: Date.now() + index }
      ] } });
      sessionIds.push(recorded.body.sessionId);
      await setSessionAutomation(recorded.body.sessionId, 'loop');
    }
    const resumed = await resumeAutomationChats();
    expect(resumed).toMatchObject({ eligible: 2, queued: 2, alreadyActive: 0 });
    await flushDurable();
    expect((await readDurable<any>('bridge-commands'))?.resumeBoundary?.conversationIds?.sort())
      .toEqual([...chats].sort());
    const firstBatch = (await request('GET', '/status')).body.repairs ?? [];
    expect(firstBatch).toHaveLength(1);
    expect(firstBatch[0]).toMatchObject({ reason: 'automation' });
    // The second exact root remains queued behind maxActiveChats=1. A new status pass cannot
    // hand it out merely because Chrome collected the first browser action.
    expect((await request('GET', '/status')).body.repairs).toEqual([]);

    // The first reload starts real provider work. That exact turn owns the only slot, so a
    // repeated Resume keeps the other root saved instead of publishing another browser action.
    const firstChat = firstBatch[0].conversationId as string;
    const firstSession = sessionIds[chats.indexOf(firstChat)]!;
    await request('POST', '/events', { body: { conversationId: firstChat, events: [
      { kind: 'turn_start', turnId: 'resume-live-turn', time: Date.now() + 10 }
    ] } });
    expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({
      eligible: 2, queued: 0, alreadyActive: 1, recovering: 1
    });

    // Once that root reaches a real terminal and is intentionally disabled, the already-saved
    // second root is handed out automatically without another click or prompt reconstruction.
    await request('POST', '/events', { body: { conversationId: firstChat, events: [
      { kind: 'assistant_message', turnId: 'resume-live-turn', messageId: 'resume-live-final',
        text: 'This bounded turn is complete.', state: 'final', final: true, goalEligible: true, time: Date.now() + 11 },
      { kind: 'turn_end', turnId: 'resume-live-turn', outcome: 'completed', time: Date.now() + 12 }
    ] } });
    await setSessionAutomation(firstSession, 'off');
    const [replenished] = (await request('GET', '/status')).body.repairs ?? [];
    expect(replenished).toMatchObject({ reason: 'automation' });
    expect(replenished.conversationId).not.toBe(firstChat);
    expect(sessionIds.map(sessionId => continuationForSession(sessionId))).toEqual([null, null]);
  } finally {
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
    vi.useRealTimers();
  }
});

