it('atomically resumes one retained confirmed-unsent Loop continuation without an Off gap or a new UUID', async () => {
  const previous = getConfig();
  const input = await import('../src/main/session/input.js');
  const chat = 'a7070707-1111-4111-8111-000000000007';
  try {
    await saveConfig({
      ...previous,
      sessions: { ...previous.sessions, record: true },
      goal: { ...previous.goal, backend: 'api', enabled: false },
      ui: { ...previous.ui, automationPaused: false, automationProfile: 'day' },
      multiAgent: { ...previous.multiAgent, limitAutomaticChats: false }
    });
    await setSecret('openRouterApiKey', 'test-atomic-resume-key');
    await pair();
    const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
      { kind: 'user_message', messageId: 'atomic-resume-question', text: 'Finish the retained task', time: Date.now() },
      { kind: 'turn_start', turnId: 'atomic-resume-turn', time: Date.now() + 1 },
      { kind: 'assistant_message', messageId: 'atomic-resume-final', turnId: 'atomic-resume-turn',
        text: 'A safe checkpoint is ready.', state: 'final', final: true, goalEligible: true, activeNow: true,
        time: Date.now() + 2 },
      { kind: 'turn_end', turnId: 'atomic-resume-turn', outcome: 'completed', time: Date.now() + 3 }
    ] } });
    const sessionId = recorded.body.sessionId as string;
    await setSessionAutomation(sessionId, 'loop');
    const pendingBefore = goalPendingReplyFor(chat);
    expect(pendingBefore).toMatchObject({ sessionId, turnId: 'atomic-resume-turn' });

    const helperId = randomUUID();
    const outgoingId = randomUUID();
    const createdAt = Math.max(1, pendingBefore!.acceptedAt);
    await writeDurableNow('session-input', [
      {
        id: helperId, sessionId: null, text: '[Temporary planner]', mode: 'auto', dueAt: createdAt,
        model: null, reasoningEffort: null, purpose: 'decision', lifetime: 'temporary-planner',
        decisionSourceSessionId: sessionId, decisionSourceTurnId: pendingBefore!.turnId,
        state: 'sent', owner: 'atomic-resume-helper-page', createdAt, conversationId: null,
        deliveredAt: createdAt, messageId: 'atomic-resume-native-helper'
      },
      {
        id: outgoingId, sessionId, text: 'Continue the exact retained implementation', mode: 'after-turn',
        dueAt: createdAt, model: null, reasoningEffort: null, sourceHelperId: helperId,
        sourceHelperAcceptedAt: pendingBefore!.acceptedAt, state: 'failed', owner: null, createdAt,
        conversationId: chat, requiresAuthorization: true, preSendReoffers: 3
      }
    ]);
    input.resetInputForTests();

    const offered = await request('GET', `/activity?conversationId=${chat}`);
    expect(offered.body.goal).toMatchObject({ enabled: true, mode: 'loop', resumeAvailable: true });

    // A stale button cannot use per-chat Resume to bypass the account-wide pause. The exact
    // reply epoch and outbox row stay untouched for a later deliberate retry.
    await saveConfig({ ...getConfig(), ui: { ...getConfig().ui, automationPaused: true } });
    expect((await request('GET', `/activity?conversationId=${chat}`)).body.goal.resumeAvailable).toBe(false);
    const paused = await request('POST', '/settings', { body: { conversationId: chat, loop: true } });
    expect(paused.status).toBe(423);
    expect(paused.body.error).toBe('automation_paused');
    expect(goalPendingReplyFor(chat)?.acceptedAt).toBe(pendingBefore!.acceptedAt);
    expect((await input.listInputs()).find(row => row.id === outgoingId)?.sourceHelperAcceptedAt)
      .toBe(pendingBefore!.acceptedAt);

    await saveConfig({ ...getConfig(), ui: { ...getConfig().ui, automationPaused: false } });
    const resumed = await request('POST', '/settings', { body: { conversationId: chat, loop: true } });
    expect(resumed.status).toBe(200);
    expect(resumed.body.goal).toMatchObject({ enabled: true, mode: 'loop', resumeAvailable: false });
    const pendingAfter = goalPendingReplyFor(chat);
    expect(pendingAfter).toMatchObject({
      sessionId,
      replyId: pendingBefore!.replyId,
      turnId: pendingBefore!.turnId
    });
    expect(pendingAfter!.acceptedAt).toBeGreaterThan(pendingBefore!.acceptedAt);
    const rows = await input.listInputs();
    expect(rows.filter(row => row.id === outgoingId)).toHaveLength(1);
    expect(rows.filter(row => row.id === helperId)).toHaveLength(1);
    expect(rows.find(row => row.id === outgoingId)).toMatchObject({
      state: 'failed', owner: null, sourceHelperId: helperId,
      sourceHelperAcceptedAt: pendingAfter!.acceptedAt, preSendReoffers: 3
    });
    expect(rows.filter(row => row.sourceHelperId === helperId)).toHaveLength(1);
    expect(((await request('GET', '/status')).body.repairs ?? [])).toEqual([
      expect.objectContaining({ conversationId: chat, reason: 'automation' })
    ]);
  } finally {
    await writeDurableNow('session-input', []);
    input.resetInputForTests();
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
  }
});

