it('parks a composer-blocked Goal/Loop recovery on its exact token without spending or replaying it', async () => {
  vi.useFakeTimers({ toFake: ['Date'] });
  try {
    await setSecret('openRouterApiKey', 'test-composer-blocked-defer-key');
    await pair();
    const chat = 'a6767676-1111-4111-8111-000000000028';
    const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
      { kind: 'user_message', messageId: 'composer-blocked-question', text: 'Keep this loop working', time: Date.now() },
      { kind: 'turn_start', turnId: 'composer-blocked-finished', time: Date.now() + 1 },
      { kind: 'assistant_message', messageId: 'composer-blocked-final', turnId: 'composer-blocked-finished',
        text: 'Paused at a safe checkpoint.', state: 'final', final: true, goalEligible: true, time: Date.now() + 2 },
      { kind: 'turn_end', turnId: 'composer-blocked-finished', outcome: 'completed', time: Date.now() + 3 }
    ] } });
    await setSessionAutomation(recorded.body.sessionId, 'loop');
    expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({ queued: 1 });
    const replyId = goalPendingReplyFor(chat)?.replyId;
    const first = ((await request('GET', '/status')).body.repairs ?? []).find((entry: any) =>
      entry.conversationId === chat);
    expect(first).toMatchObject({ conversationId: chat, reason: 'automation', requiresClaim: true });
    expect((await request('POST', '/repairs/claim', { body: { token: first.token } })).body.allowed).toBe(true);

    const deferred = await request('GET',
      `/status?repairDeferred=${encodeURIComponent(first.token)}&repairCause=composer-blocked`);
    expect(deferred.body.repairs).toEqual([]);
    expect(goalPendingReplyFor(chat)?.replyId).toBe(replyId);

    // Polling, the ordinary receipt timeout and late duplicate receipts cannot create a second
    // owner or misreport a browser action that never happened.
    vi.setSystemTime(Date.now() + 60_000);
    expect(((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
      entry.conversationId === chat)).toEqual([]);
    expect((await request('POST', '/repairs/claim', { body: { token: first.token } })).body.allowed).toBe(false);
    await request('GET', `/status?repaired=${encodeURIComponent(first.token)}&repairAction=nudged`);
    expect(((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
      entry.conversationId === chat)).toEqual([]);

    const view = (await automationSupervisorSnapshot()).chats.find(row => row.conversationId === chat);
    expect(view).toMatchObject({
      state: 'recovering',
      recoveryStage: 'waiting-browser',
      spinning: false
    });
    expect(view?.reason).toContain('unsent user text');
    expect(view?.nextAction).toContain('Review that draft');

    // Explicit user recovery is the only boundary that replaces the parked token. The durable
    // reply is still the same one and the refunded attempt receives a fresh exact handout. The
    // parked handout never performed an action, so this remains true even inside the ordinary
    // recent-handout grace window.
    vi.setSystemTime(Date.now() - 60_000 + 1);
    expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({ queued: 1 });
    const second = ((await request('GET', '/status')).body.repairs ?? []).find((entry: any) =>
      entry.conversationId === chat);
    expect(second).toMatchObject({ conversationId: chat, reason: 'automation' });
    expect(second.token).not.toBe(first.token);
    expect(goalPendingReplyFor(chat)?.replyId).toBe(replyId);
  } finally {
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    vi.useRealTimers();
  }
});

it('protects a repair tab through queue, handout, and confirmed activity wait, then releases it', async () => {
  const chat = 'a6767676-1111-4111-8111-000000000008';
  try {
    await pair();
    await request('POST', '/events', { body: { conversationId: chat, events: [
      { kind: 'user_message', messageId: 'repair-policy-question', text: 'Finish this ordinary task', time: Date.now() },
      { kind: 'turn_start', turnId: 'repair-policy-broken', time: Date.now() },
      { kind: 'chat_error', turnId: 'repair-policy-broken', text: 'Connection interrupted. Waiting for the complete answer',
        recoverable: true, time: Date.now() }
    ] } });

    // browserTabPolicy runs before this status pass hands the queued repair to Chrome.
    const queued = (await request('POST', '/status', { body: { openConversations: [chat] } })).body;
    expect(queued.nonDiscardableConversations).toContain(chat);
    const handout = queued.repairs.find((entry: any) => entry.conversationId === chat);
    expect(handout).toMatchObject({ conversationId: chat, reason: 'assistant-error' });

    // Missing acknowledgement retains the handed repair and its discard protection.
    const handed = (await request('POST', '/status', { body: { openConversations: [chat] } })).body;
    expect(handed.nonDiscardableConversations).toContain(chat);
    expect((await request('POST', '/repairs/claim', { body: { token: handout.token } })).body.allowed).toBe(true);

    // The receipt moves the repair to done, and awaitingReturn owns protection until the page
    // proves it has progressed beyond the broken answer.
    const receipt = (await request('GET', `/status?repaired=${encodeURIComponent(handout.token)}&repairAction=reloaded`)).body;
    expect(receipt.nonDiscardableConversations).toContain(chat);
    const awaitingActivity = (await request('POST', '/status', { body: { openConversations: [chat] } })).body;
    expect(awaitingActivity.nonDiscardableConversations).toContain(chat);

    // Blocking retires every browser-recovery authority. The policy must release the tab on
    // the next policy snapshot after takePendingRepairs has retired the handed token.
    setChatBlocked(chat, true);
    await request('POST', '/status', { body: { openConversations: [chat] } });
    const retired = (await request('POST', '/status', { body: { openConversations: [chat] } })).body;
    expect(retired.nonDiscardableConversations).not.toContain(chat);
  } finally {
    setChatBlocked(chat, false);
  }
});

it.each([
  ['global Resume', true, true, false, true],
  ['global Pause', false, true, true, true],
  ['chat Resume', false, false, false, true],
  ['chat Pause', false, true, false, false]
] as const)('publishes current supervisor state after %s during supersession lookup', async (_label, beforePaused, beforeEnabled, afterPaused, afterEnabled) => {
  const previous = getConfig();
  let entered!: () => void, release!: () => void;
  const reached = new Promise<void>(resolve => { entered = resolve; });
  const held = new Promise<void>(resolve => { release = resolve; });
  let publication: ReturnType<typeof automationSupervisorSnapshot> | undefined;
  let lookup: ReturnType<typeof vi.spyOn> | undefined;
  try {
    await setSecret('openRouterApiKey', 'test-supervisor-publication-key');
    await saveConfig({ ...previous, ui: { ...previous.ui, automationPaused: beforePaused } });
    const conversationId = randomUUID();
    const session = await createSession({ conversationId, title: 'Supervisor publication race' });
    await setGoalObjectiveNow(conversationId, 'Keep the exact retained task');
    await setGoalSwitchNow(conversationId, 'loop', beforeEnabled);
    const replies = JSON.stringify(snapshotGoalReplies().replies);
    const commands = JSON.stringify(pendingCommands());
    const realLookup = sessionStoreModule.conversationWasSuperseded;
    lookup = vi.spyOn(sessionStoreModule, 'conversationWasSuperseded').mockImplementationOnce(async id => {
      entered();
      await held;
      return realLookup(id);
    });
    publication = automationSupervisorSnapshot([session]);
    await reached;
    await saveConfig({ ...getConfig(), ui: { ...getConfig().ui, automationPaused: afterPaused } });
    await setGoalSwitchNow(conversationId, 'loop', afterEnabled);
    release();
    const chat = (await publication).chats.find(row => row.conversationId === conversationId);
    expect(chat).toBeDefined();
    if (afterPaused || !afterEnabled) expect(chat?.state).toBe('paused');
    else expect(chat?.state).not.toBe('paused');
    expect(chat?.pause !== undefined).toBe(!afterEnabled);
    expect(goalObjectiveFor(conversationId)).toBe('Keep the exact retained task');
    expect(JSON.stringify(snapshotGoalReplies().replies)).toBe(replies);
    expect(JSON.stringify(pendingCommands())).toBe(commands);
  } finally {
    release();
    await publication;
    lookup?.mockRestore();
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
  }
});

