it('does not let unattributed tool execution refresh every automated chat presentation', async () => {
  const previous = getConfig();
  let releaseUnattributed = () => {};
  let releaseExact = () => {};
  let unattributedTool: Promise<void> = Promise.resolve();
  let exactTool: Promise<void> = Promise.resolve();
  try {
    await saveConfig({ ...previous, goal: { ...previous.goal, enabled: false, mode: 'loop' } });
    await setSecret('openRouterApiKey', 'test-exact-tool-owner-key');
    await pair();
    const conversations = [
      'a6262626-1111-4111-8111-000000000002',
      'a6161616-1111-4111-8111-000000000001'
    ];
    for (const [index, conversationId] of conversations.entries()) {
      const recorded = await request('POST', '/events', { body: { conversationId, events: [
        { kind: 'user_message', messageId: `tool-owner-question-${index}`, text: 'Keep this loop moving', time: Date.now() + index }
      ] } });
      await setSessionAutomation(recorded.body.sessionId, 'loop');
    }
    const observationAt = Date.now() + AUTOMATION_STALE_MS + 5_000;
    const baseline = await automationSupervisorSnapshot(undefined, observationAt);
    for (const conversationId of conversations) {
      expect(baseline.chats).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId, state: 'waiting-main', spinning: false,
          reason: expect.stringContaining('no exact reply') })
      ]));
    }

    const { trackInFlight, emptyEvidence } = await import('../src/main/mcp/call-context.js');
    unattributedTool = trackInFlight({ startedAt: Date.now(), transportKey: null, agent: null, outcome: null,
      evidence: emptyEvidence(), caller: { conversationId: null, requestId: 'unattributed-presentation-call', transportKey: null } },
      () => new Promise<void>(resolve => { releaseUnattributed = resolve; }));
    const unattributedSnapshot = await automationSupervisorSnapshot(undefined, observationAt);
    for (const conversationId of conversations) {
      expect(unattributedSnapshot.chats).toEqual(expect.arrayContaining([
        expect.objectContaining({ conversationId, state: 'waiting-main', spinning: false,
          reason: expect.stringContaining('no exact reply') })
      ]));
    }
    releaseUnattributed();
    await unattributedTool;

    exactTool = trackInFlight({ startedAt: Date.now(), transportKey: null, agent: null, outcome: null,
      evidence: emptyEvidence(), caller: { conversationId: conversations[0]!, requestId: 'exact-presentation-call', transportKey: null } },
      () => new Promise<void>(resolve => { releaseExact = resolve; }));
    const exactSnapshot = await automationSupervisorSnapshot(undefined, observationAt);
    expect(exactSnapshot.chats).toEqual(expect.arrayContaining([
      expect.objectContaining({ conversationId: conversations[0], state: 'working', spinning: true }),
      expect.objectContaining({ conversationId: conversations[1], state: 'waiting-main', spinning: false,
        reason: expect.stringContaining('no exact reply') })
    ]));
  } finally {
    releaseUnattributed();
    releaseExact();
    await Promise.all([unattributedTool, exactTool]);
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
  }
});

