it.each([false, true])('releases a confirmed quiet automation wake slot to the next staged root (background staged: %s)', async backgroundStaged => {
  const previous = getConfig();
  vi.useFakeTimers({ toFake: ['Date'] });
  try {
    await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, limitAutomaticChats: true, maxActiveChats: 1 } });
    await setSecret('openRouterApiKey', 'test-idle-reload-key');
    await pair();
    const chats = [
      'a6767676-1111-4111-8111-000000000006',
      'a7878787-1111-4111-8111-000000000007'
    ];
    for (const [index, chat] of chats.entries()) {
      const recorded = await request('POST', '/events', { body: { conversationId: chat, events: [
        { kind: 'user_message', messageId: `idle-reload-question-${index}`, text: 'Keep this loop working', time: Date.now() + index },
        { kind: 'turn_start', turnId: `idle-reload-turn-${index}`, time: Date.now() + index },
        { kind: 'assistant_message', messageId: `idle-reload-final-${index}`, turnId: `idle-reload-turn-${index}`,
          text: 'Waiting at a checkpoint.', state: 'final', final: true, goalEligible: true, time: Date.now() + index },
        { kind: 'turn_end', turnId: `idle-reload-turn-${index}`, outcome: 'completed', time: Date.now() + index }
      ] } });
      await setSessionAutomation(recorded.body.sessionId, 'loop');
    }
    if (backgroundStaged) expect(await resumeAutomationChats({ maxQueued: 1 })).toMatchObject({ queued: 1 });
    const resumed = await resumeAutomationChats();
    expect(resumed).toMatchObject({ eligible: 2, alreadyActive: 0 });
    // The existing backfill may stage one root before the explicit Resume.
    // Count both exact staged owners; retain the one-lane handout proof below.
    expect(resumed.queued + resumed.recovering).toBe(2);
    const first = ((await request('GET', '/status')).body.repairs ?? [])[0];
    expect(first).toMatchObject({ reason: 'automation' });
    expect((await request('GET', `/status?repaired=${first.token}&repairAction=nudged`)).body.repairs).toEqual([]);

    vi.setSystemTime(Date.now() + 45_001);
    const next = (await request('GET', '/status')).body.repairs ?? [];
    expect(next).toHaveLength(1);
    expect(next[0]).toMatchObject({ reason: 'automation' });
    expect(next[0].conversationId).not.toBe(first.conversationId);
  } finally {
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
    vi.useRealTimers();
  }
});

it.each(['all', 'chat'] as const)('holds an exhausted quiet automation episode until explicit Resume %s', async scope => {
  const previous = getConfig();
  const notices: Array<{ title: string; body: string; sessionId: string }> = [];
  setUserNoticeNotifier((title, body, sessionId) => {
    notices.push({ title, body, sessionId });
    return true;
  });
  vi.useFakeTimers({ toFake: ['Date'] });
  try {
    await saveConfig({ ...previous, multiAgent: { ...previous.multiAgent, limitAutomaticChats: true, maxActiveChats: 1 } });
    await setSecret('openRouterApiKey', 'test-bounded-automation-repair-key');
    await pair();
    for (const chat of (await automationSupervisorSnapshot()).chats) await setSessionAutomation(chat.sessionId, 'off');
    const conversationId = 'a6767676-1111-4111-8111-000000000016';
    const recorded = await request('POST', '/events', { body: { conversationId, events: [
      { kind: 'user_message', messageId: 'bounded-repair-question', text: 'Keep this loop working', time: Date.now() },
      { kind: 'turn_start', turnId: 'bounded-repair-turn', time: Date.now() + 1 },
      { kind: 'assistant_message', messageId: 'bounded-repair-final', turnId: 'bounded-repair-turn',
        text: 'Ready for the next pass.', state: 'final', final: true, goalEligible: true, time: Date.now() + 2 },
      { kind: 'turn_end', turnId: 'bounded-repair-turn', outcome: 'completed', time: Date.now() + 3 }
    ] } });
    await setSessionAutomation(recorded.body.sessionId, 'loop');

    expect(await resumeAutomationChats()).toMatchObject({ queued: 1 });
    const [first] = (await request('GET', '/status')).body.repairs ?? [];
    expect(first).toMatchObject({ conversationId, reason: 'automation', requiresClaim: true });
    expect((await request('POST', '/repairs/claim', { body: { token: first.token } })).body.allowed).toBe(true);
    expect((await request('GET', `/status?repaired=${first.token}&repairAction=reloaded`)).body.repairs).toEqual([]);

    vi.setSystemTime(Date.now() + 25_001);
    const [second] = (await request('GET', '/status')).body.repairs ?? [];
    expect(second).toMatchObject({ conversationId, reason: 'automation', requiresClaim: true });
    expect((await request('POST', '/repairs/claim', { body: { token: second.token } })).body.allowed).toBe(true);
    expect(second.token).not.toBe(first.token);
    expect((await request('GET', `/status?repaired=${second.token}&repairAction=reloaded`)).body.repairs).toEqual([]);

    vi.setSystemTime(Date.now() + 25_001);
    expect((await request('GET', '/status')).body.repairs ?? []).toEqual([]);
    expect((await automationSupervisorSnapshot()).chats).toEqual(expect.arrayContaining([
      expect.objectContaining({ conversationId, state: 'stalled', recoveryStage: null, spinning: false,
        nextRetryAt: null, recoverable: true })
    ]));
    expect((await request('GET', `/activity?conversationId=${conversationId}&since=0`)).body.goal.health).toMatchObject({
      state: 'stalled', recoveryStage: null, spinning: false, nextRetryAt: null, recoverable: true
    });
    const durable = await readDurable<any>('bridge-commands');
    expect(durable?.recoveryFences).toEqual(expect.arrayContaining([
      expect.objectContaining({ conversationId })
    ]));
    expect(notices).toEqual([expect.objectContaining({
      title: 'Recovery stopped',
      body: expect.stringContaining('two bounded browser recovery attempts'),
      sessionId: recorded.body.sessionId
    })]);

    vi.setSystemTime(Date.now() + 10 * 60_000);
    await maintainLoopLanes();
    const automatic = ((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
      entry.conversationId === conversationId);
    expect(automatic).toEqual([]);
    expect((await readDurable<any>('bridge-commands'))?.recoveryFences).toEqual(expect.arrayContaining([
      expect.objectContaining({ conversationId })
    ]));
    // Repeated maintenance reads of the same durable exhausted episode stay silent.
    expect(notices).toHaveLength(1);

    if (scope === 'chat') {
      expect((await request('GET', `/activity?conversationId=${conversationId}`)).body.goal.resumeAvailable).toBe(true);
      const resumed = await request('POST', '/settings', { body: { conversationId, loop: true } });
      expect(resumed.status).toBe(200);
    } else expect(await resumeAutomationChats({ startBrowser: false })).toMatchObject({ queued: 1 });
    const explicit = ((await request('GET', '/status')).body.repairs ?? []).filter((entry: any) =>
      entry.conversationId === conversationId);
    expect(explicit).toHaveLength(1);
    expect(explicit[0]).toMatchObject({ reason: 'automation' });
    expect((await automationSupervisorSnapshot()).chats).toEqual(expect.arrayContaining([
      expect.objectContaining({ conversationId, state: 'recovering', spinning: false })
    ]));
  } finally {
    setUserNoticeNotifier(null);
    resetGoalStateForTests();
    await setSecret('openRouterApiKey', '');
    await saveConfig(previous);
    vi.useRealTimers();
  }
});

